import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from 'src/common/logger/app-logger';
import { AppConfigService } from '../app-config/app-config.service';

@Injectable()
export class ApiManagerConfigService implements OnModuleInit {
  private readonly logger: AppLogger = new AppLogger(
    ApiManagerConfigService.name,
  );

  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
  ) {}

  public async apiManager(): Promise<string> {
    let value = this.configService.get<string>('apiManagerUrl');

    if (value) {
      this.logger.warn(`'apiManagerUrl' was read from environment variable`);
    } else {
      value = await this.appConfigService.getConfigurationValue('API_MGR_URL');
    }

    return value ?? '';
  }

  public get mainSecretStore(): string {
    return this.configService.get<string>('mainSecretStore') ?? '';
  }

  public get apiMgrSecretName(): string {
    return this.configService.get<string>('apiMgrKeySecretName') ?? '';
  }

  public get mesPasswordSecretName(): string {
    return this.configService.get<string>('mesPasswordSecretName') ?? '';
  }

  public async mesUserName(): Promise<string> {
    let value = this.configService.get<string>('mesUser');

    if (value) {
      this.logger.warn(`'mesUserName' was read from environment variable`);
    } else {
      value = await this.appConfigService.getConfigurationValue('MES_USER');
    }

    return value ?? '';
  }

  public async apiManagerEnabled(): Promise<boolean> {
    const value = this.configService.get<string>('apiMgrEnabled');

    if (value === undefined) {
      const appStoreValue =
        await this.appConfigService.getConfigurationValue('API_MGR_ENABLED');

      return appStoreValue?.toLowerCase() === 'true';
    }
    this.logger.warn(`'apiMgrEnabled' was read from environment variable`);

    return value?.toLowerCase() === 'true';
  }

  public async onModuleInit(): Promise<void> {
    await this.checkConfiguration();
  }

  private async checkConfiguration(): Promise<void> {
    if (!(await this.appConfigService.reachable())) {
      const storeNotReachableMessage = `App Configuration Store '${this.appConfigService.configStoreId}' is not reachable !`;

      this.logger.error(storeNotReachableMessage);
      throw new Error(storeNotReachableMessage);
    }

    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'mainSecretStore', value: this.mainSecretStore },
      { key: 'mesPasswordSecretName', value: this.mesPasswordSecretName },
      { key: 'mesUserName', value: await this.mesUserName() },
    ];
    const apiMgrEnabled = await this.apiManagerEnabled();

    if (apiMgrEnabled) {
      requiredConfigs.push(
        { key: 'apiMgrKeySecretName', value: this.apiMgrSecretName },
        { key: 'apiManagerUrl', value: await this.apiManager() },
      );
    }

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

  }
}

interface Config {
  apiManagerUrl: string | undefined;
  apiMgrEnabled: string | undefined;
  apiMgrKeySecretName: string | undefined;
  mainSecretStore: string | undefined;
  mesPasswordSecretName: string | undefined;
  mesUser: string | undefined;
}

const apiManagerConfig = (): Config => ({
  apiManagerUrl: process.env.API_MGR_URL,
