import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';
import { AppConfigService } from '@/config/app-config/app-config.service';

@Injectable()
export class WkIntegrationConfigService implements OnModuleInit {
  private readonly logger: AppLogger = new AppLogger(
    WkIntegrationConfigService.name,
  );

  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
  ) {}

  public async timeoutProcessWkData(): Promise<number> {
    const timeoutProcessWkDataEnvironment = this.configService.get<string>(
      'timeoutProcessWkData',
    );

    if (timeoutProcessWkDataEnvironment === undefined) {
      const appStoreValue = Number(
        await this.appConfigService.getConfigurationValue(
          'WK_INTEGRATION_TIMEOUT_PROCESS_WK_DATA_SECONDS',
        ),
      );
      return Number.isNaN(appStoreValue) ? 60 : (appStoreValue ?? 60);
    }
    this.logger.warn(
      `'timeouit process wk data' was read from environment variable`,
    );
    const timeOut = Number(timeoutProcessWkDataEnvironment);
    return Number.isNaN(timeOut) ? 60 : (timeOut ?? 60);
  }

  public async onModuleInit(): Promise<void> {
    await this.checkConfiguration();
  }

  private async checkConfiguration(): Promise<void> {
    if (!(await this.appConfigService.reachable())) {
      const storeNotReachableMessage = `App Configuration Store '${this.appConfigService.configStoreId}' is not reachable !`;

      this.logger.error(storeNotReachableMessage);
      throw new Error(storeNotReachableMessage);
    }

    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      {
        key: 'timeoutProcessWkData',
        value: await this.timeoutProcessWkData(),
      },
    ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

  }
}

import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import * as bodyParser from 'body-parser';
import { AppModule } from '@/app.module';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';

/**
 * Main entrypoint of the application
 */
async function bootstrap(): Promise<void> {
  const MIME_TYPE_XML = 'text/xml';
  const app = await NestFactory.create(AppModule);
  app.use(bodyParser.raw({ limit: '50mb', type: MIME_TYPE_XML }));
  app.useGlobalPipes(new ValidationPipe());
  app.enableCors({
    allowedHeaders: 'Content-Type,Authorization',
    origin: '*',
  });

  const { urlApi } = app.get(UrlApiConfigService);

  const config = new DocumentBuilder()
    .setTitle('Backend WK Integration Swagger Documentation')
    .setDescription(
      "In this page you'll find all of the necessary informations about the microservice Backend WK Integration and it's different endpoints.",
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .addBasicAuth(
      {
        scheme: 'basic',
        type: 'http',
      },
      'basic', // Name of the security scheme, can be used to apply security to specific routes
    )
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api', app, document, {
    swaggerOptions: {
      // This will make Swagger UI prompt for Basic Auth credentials
      authAction: {
        basic: {
          name: 'basic', // Security scheme name should match the one in DocumentBuilder
          schema: {
            in: 'header',
            name: 'Authorization',
            scheme: 'basic',
            type: 'http',
          },
        },
      },
    },
  });
  app.use(
    '/wk-integration/automatic-wk-integration',
    bodyParser.text({ type: MIME_TYPE_XML }),
  );
  app.use(
    '/wk-integration/automatic-wk-integration-preactor',
    bodyParser.text({ type: MIME_TYPE_XML }),
  );
  await app.listen(3000);
}
bootstrap();

