import { Injectable, Logger } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { AuthConfigService } from '@/config/auth/auth-config.service';

@Injectable()
export class AuthService {
  private readonly daprClient: DaprClient;

  public constructor(private readonly authConfigService: AuthConfigService) {
    this.daprClient = new DaprClient();
  }

  public async validateUser(
    username: string,
    password: string,
  ): Promise<string> {
    const secretUserName = await this.authConfigService.secretUserName();
    const { secretUsernameKeyPassword } = this.authConfigService;
    const { mainSecretStore } = this.authConfigService;

    const passKeyObject = await this.daprClient.secret.get(
      mainSecretStore,
      secretUsernameKeyPassword,
    );
    const passKeyValue = Object.values(passKeyObject)[0];
    if (passKeyValue) {
      Logger.debug(`password ${passKeyValue.slice(0, 4)}`);
    } else {
      Logger.debug(`password  is empty `);
    }
    if (username === secretUserName && password === passKeyValue) {
      Logger.debug(`username ${username} `);

      return username; // Return a user object
    }
    return '';
  }
}

