import { Injectable } from '@nestjs/common';
import { DaprClient, HttpMethod } from 'dapr-client';

import { KanbanItemService } from '../wk-integration/sub-services/kanban-item.service';
import { PlantService } from '../wk-integration/sub-services/plant.service';
import { bufferLineToKanbanData } from './dtos/buffer-line-to-kanban-data.dto';
import { ReprocessResultDto } from './dtos/reprocess-result.dto';
import { SingleReprocessResultDto } from './dtos/single-reprocess-result.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';

@Injectable()
export class ReprocessBufferService {
  private readonly daprClient: DaprClient;

  private readonly logger = new AppLogger(ReprocessBufferService.name);

  public constructor(
    private readonly urlApiConfigService: UrlApiConfigService,
    private readonly kanbanItemService: KanbanItemService,
    private readonly plantService: PlantService,
  ) {
    this.daprClient = new DaprClient();
  }

  /**
   * Orchestrate the reprocess of all orders sequentially.
   * @param orderIds - List of order IDs to reprocess
   * @returns Detailed results and summary
   */
  public async reprocessOrders(
    orderIds: Array<string>,
  ): Promise<ReprocessResultDto> {
    // Process each order sequentially to avoid race conditions on check-processing
    const processedResults = await this.processOrdersSequentially(orderIds);

    const summary = {
      error: processedResults.filter((r) => r.status === 'error').length,
      rejected: processedResults.filter((r) => r.status === 'rejected').length,
      success: processedResults.filter((r) => r.status === 'success').length,
      total: processedResults.length,
    };

    return { results: processedResults, summary };
  }

  /**
   * Process orders one by one recursively to avoid no-await-in-loop lint rule.
   * @param orderIds - Remaining order IDs to process
   * @param accumulated - Results accumulated so far
   * @returns All processed results
   */
  private async processOrdersSequentially(
    orderIds: Array<string>,
    accumulated: Array<SingleReprocessResultDto> = [],
  ): Promise<Array<SingleReprocessResultDto>> {
    if (orderIds.length === 0) {
      return accumulated;
    }

    const [currentOrderId, ...remainingOrderIds] = orderIds;
    const result = await this.reprocessSingleOrder(currentOrderId);

    return this.processOrdersSequentially(remainingOrderIds, [
      ...accumulated,
      result,
    ]);
  }

  /**
   * Process a single order through all reprocess steps.
   * @param orderId - The order ID to reprocess
   * @returns The result for this single order
   */
  public async reprocessSingleOrder(
    orderId: string,
  ): Promise<SingleReprocessResultDto> {
    let logId: number | null = null;

    try {
      // Step 1: Get latest buffer line
      this.logger.log(`[${orderId}] Step 1: Fetching latest buffer line`);
      const bufferLine = await this.getLatestBufferLine(orderId);

      if (!bufferLine) {
        return {
          message: 'Order not found in buffer',
          orderId,
          status: 'error',
        };
      }

      const plant = String(bufferLine.plant);
      const bufferId = bufferLine.id;

      // Step 2: Check if already processing
      this.logger.log(`[${orderId}] Step 2: Checking if already processing`);
      const isProcessing = await this.checkIfProcessing(orderId, plant);

      if (isProcessing) {
        return {
          message: 'Order already being processed',
          orderId,
          status: 'rejected',
        };
      }

      // Step 3: Create processing log
      this.logger.log(`[${orderId}] Step 3: Creating processing log`);
      logId = await this.createProcessingLog(
        orderId,
        plant,
        JSON.stringify(bufferLine),
      );

      // Step 4: Run validations and update buffer entry
      this.logger.log(
        `[${orderId}] Step 4: Running WK validations and updating buffer entry`,
      );
      const kanbanData = bufferLineToKanbanData(bufferLine);

      // Get plant info for validations
      const plantInfo = (await this.plantService.getPlantById(
        bufferLine.plant,
      )) as { timezone: string };

      // Get mandatory dates flag
      let mandatoryDatesFromPreactor = false;
      try {
        const plantFlags = (await this.plantService.getPlantConfigFlags(
          bufferLine.plant,
        )) as {
          mandatoryDatesFromPreactor: boolean;
        };
        mandatoryDatesFromPreactor = plantFlags.mandatoryDatesFromPreactor;
      } catch {
        this.logger.warn(
          `[${orderId}] Failed to get plant config flags, using default`,
        );
      }

      // Run the same checks as WK integration and UPDATE the existing buffer entry
      const result = await this.kanbanItemService.reprocessKanbanItem(
        kanbanData,
        bufferLine.plant,
        plantInfo,
        mandatoryDatesFromPreactor,
        bufferId,
      );

      const isSuccess = result.STATUS === 'SUCCESS';

      // Step 5a: Mark log as success or error based on validation result
      if (isSuccess) {
        this.logger.log(`[${orderId}] Step 5a: Marking log as success`);
        await this.markLogAsSuccess(logId);

        return {
          message: 'Reprocess completed successfully',
          orderId,
          status: 'success',
        };
      }

      // Validations failed — mark log as error with the validation errors
      this.logger.log(
        `[${orderId}] Step 5b: Validations failed, marking log as error`,
      );
      await this.markLogAsError(logId, result.ERROR || 'Validation errors');

      return {
        message: `Reprocess completed with errors: ${result.ERROR}`,
        orderId,
        status: 'error',
      };
    } catch (error_) {
      this.logger.error(
        `[${orderId}] Error during reprocess: ${error_.message}`,
      );

      // Step 5b: If log was created, mark it as error
      if (logId) {
        try {
          await this.markLogAsError(
            logId,
            error_.message || 'Unknown error during reprocess',
          );
        } catch (logError) {
          this.logger.error(
            `[${orderId}] Failed to mark log ${logId} as error: ${logError.message}`,
          );
        }
      }

      return {
        message: `Error during reprocess: ${error_.message}`,
        orderId,
        status: 'error',
      };
    }
  }

  /**
   * Get the latest buffer line for an orderId.
   * @param orderId - The order ID
   * @returns The buffer line object or null if not found
   */
  public async getLatestBufferLine(
    orderId: string,
  ): Promise<{ id: number; plant: number; [key: string]: unknown } | null> {
    const { urlOrderApi } = this.urlApiConfigService;
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const serviceMethod = `buffer/latest/${orderId}`;

    try {
      const response = await this.daprClient.invoker.invoke(
        urlOrderApi,
        serviceMethod,
        HttpMethod.GET,
        undefined,
        options,
      );
      // If the response contains an "error" field, the order was not found
      if (
        response &&
        typeof response === 'object' &&
        'error' in (response as Record<string, unknown>)
      ) {
        this.logger.warn(
          `[${orderId}] Order not found in buffer: ${(response as Record<string, unknown>).error}`,
        );
        return null;
      }

      return response as { id: number; plant: number; [key: string]: unknown };
    } catch (error_) {
      this.logger.error(
        `[${orderId}] Failed to fetch latest buffer line: ${error_.message}`,
      );
      throw new Error(`Failed to fetch buffer line: ${error_.message}`);
    }
  }

  /**
   * Check if an order is already being processed.
   * @param orderId - The order ID
   * @param plant - The plant (as string)
   * @returns true if processing, false otherwise
   */
  public async checkIfProcessing(
    orderId: string,
    plant: string,
  ): Promise<boolean> {
    const { urlOrderApi } = this.urlApiConfigService;
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const serviceMethod = `log-buffer-history/check-processing/${orderId}/${plant}`;

    try {
      const response = await this.daprClient.invoker.invoke(
        urlOrderApi,
        serviceMethod,
        HttpMethod.GET,
        undefined,
        options,
      );

      return (response as { isProcessing: boolean }).isProcessing;
    } catch (error_) {
      this.logger.error(
        `[${orderId}] Failed to check processing status: ${error_.message}`,
      );
      throw new Error(`Failed to check processing status: ${error_.message}`);
    }
  }

  /**
   * Create a log entry with PROCESSING status.
   * @param orderId - The order ID
   * @param plant - The plant (as string)
   * @param bufferData - JSON stringified buffer line snapshot
   * @returns The created log ID
   */
  public async createProcessingLog(
    orderId: string,
    plant: string,
    bufferData: string,
  ): Promise<number> {
    const { urlOrderApi } = this.urlApiConfigService;
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const serviceMethod = `log-buffer-history`;

    const payload = {
      actionType: 'reprocess',
      bufferData,
      errorMessage: null,
      orderId,
      plant,
      status: 'PROCESSING',
    };

    try {
      const response = await this.daprClient.invoker.invoke(
        urlOrderApi,
        serviceMethod,
        HttpMethod.POST,
        payload,
        options,
      );

      return (response as { id: number }).id;
    } catch (error_) {
      this.logger.error(
        `[${orderId}] Failed to create processing log: ${error_.message}`,
      );
      throw new Error(`Failed to create processing log: ${error_.message}`);
    }
  }

  /**
   * Mark a log entry as SUCCESS.
   * @param logId - The log entry ID
   */
  public async markLogAsSuccess(logId: number): Promise<void> {
    const { urlOrderApi } = this.urlApiConfigService;
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const serviceMethod = `log-buffer-history/${logId}/mark-success`;

    try {
      await this.daprClient.invoker.invoke(
        urlOrderApi,
        serviceMethod,
        HttpMethod.PUT,
        undefined,
        options,
      );
    } catch (error_) {
      this.logger.error(
        `Failed to mark log ${logId} as success: ${error_.message}`,
      );
      throw new Error(`Failed to mark log as success: ${error_.message}`);
    }
  }

  /**
   * Mark a log entry as ERROR with an error message.
   * @param logId - The log entry ID
   * @param errorMessage - The error detail message
   */
  public async markLogAsError(
    logId: number,
    errorMessage: string,
  ): Promise<void> {
    const { urlOrderApi } = this.urlApiConfigService;
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const serviceMethod = `log-buffer-history/${logId}/mark-error`;

    try {
      await this.daprClient.invoker.invoke(
        urlOrderApi,
        serviceMethod,
        HttpMethod.PUT,
        { errorMessage },
        options,
      );
    } catch (error_) {
      this.logger.error(
        `Failed to mark log ${logId} as error: ${error_.message}`,
      );
      throw new Error(`Failed to mark log as error: ${error_.message}`);
    }
  }
}

