import { XMLBuilder } from 'fast-xml-parser';
import { ShoporderResponseDTO } from '../dtos/shoporder-response.dto';
import { convertFromUTC } from '@/utils/date';

export class ShopOrderXmlConverter {
  // Static method to map camelCase DTO properties to uppercase XML keys
  private static mapToUpperCaseKeys(
    item: ShoporderResponseDTO,
    timezone: string,
  ): Record<string, string | number | boolean | null | undefined | Date> {
    return {
      SHOP_ORDER: item.shopOrder,
      WORK_CENTER: item.workCenter,
      MATERIAL: item.material,
      KANBAN_TYPE: item.kanbanType,
      QTY_TO_BUILD: item.qtyToBuild,
      QTY_DONE: item.qtyDone,
      QTY_SCRAPPED: item.qtyScrapped,
      RELATED_ORDER: item.relatedOrder,
      CREATED_PROD_SO: item.createdProdSo,
      BATCH: item.batch,
      BATCH_TEST: item.batchTest,
      CUSTOMER: item.customer,
      CONTAINER_NUMBER: item.containerNumber,
      PICKING_TIME: item.pickingTime
        ? convertFromUTC(item.pickingTime, timezone)
        : '',
      PRODUCTION_TIME: item.productionTime
        ? convertFromUTC(item.productionTime, timezone)
        : '',
      FROM_STORAGE_LOC: item.fromStorageLoc,
      TO_STORAGE_LOC: item.toStorageLoc,
      FROM_STORAGE_BIN: item.fromStorageBin,
      TO_STORAGE_BIN: item.toStorageBin,
      GROUPING_SEQ: item.groupingSeq,
      PLC_ASSIGNED: item.plcAssigned,
      CUSTOM_STATUS: item.customStatus,
      DESTINATION_WC: item.destinationWc,
      TPA_CODE: item.tpaCode,
      SEBANGO: item.sebango,
      WORK_CENTER_DESCRIPTION: item.workCenterDescription,
      CUSTOMER_DESCRIPTION: item.customerDescription,
    };
  }

  private readonly builder: XMLBuilder;

  public constructor() {
    // XML formatting options
    const options = {
      format: true,
      suppressBooleanAttributes: false,
      suppressEmptyNode: true,
    };
    this.builder = new XMLBuilder(options);
  }

  // Main method to convert an array of ShoporderResponseDTO to XML
  public convertToXml(
    data: Array<ShoporderResponseDTO>,
    timezone: string,
  ): string {
    const result = {
      rowsets: {
        rowset: {
          row: data.map((item) =>
            ShopOrderXmlConverter.mapToUpperCaseKeys(item, timezone),
          ), // Using arrow function
        },
      },
    };

    return this.builder.build(result); // Build and return the XML
  }
}

