export class ShopOrderService {
  private static chunkArray<T>(
    array: Array<T>,
    chunkSize: number,
  ): Array<Array<T>> {
    const chunks: Array<Array<T>> = [];
    for (let index = 0; index < array.length; index += chunkSize) {
      chunks.push(array.slice(index, index + chunkSize));
    }
    return chunks;
  }

  private readonly daprClient: DaprClient;

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  public async getSapServerByPlant(
    plant: number | Array<number>,
  ): Promise<{ sapServer: string | Array<string> }> {
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `/plant/getSapServerByPlant/${plant}`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.GET,
      undefined,
      options,
    );
    if (response) {
      return response as { sapServer: string };
    }
    throw new Error('Invalid response from getSapServerByPlant');
  }

  public async getWkOrderByCriteria(
    plantId: number,
    queryParameters: FilterDTO,
  ): Promise<string> {
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethodPlant = `plant/getPlantById/${plantId}`;
    const response = (await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethodPlant,
      HttpMethod.GET,
    )) as { timezone: string };
    const { timezone } = response;
    const updatedQueryParameters = { ...queryParameters };
    if (updatedQueryParameters.EndPickingTime) {
      const endPickingTime = convertToUTC(
        updatedQueryParameters.EndPickingTime,
        timezone,
      ).toISOString();
      updatedQueryParameters.EndPickingTime = endPickingTime;
    }
    if (updatedQueryParameters.EndProductionTime) {
      const endProductionTime = convertToUTC(
        updatedQueryParameters.EndProductionTime,
        timezone,
      ).toISOString();
      updatedQueryParameters.EndProductionTime = endProductionTime;
    }
    if (updatedQueryParameters.StartPickingTime) {
      const startPickingTime = convertToUTC(
        updatedQueryParameters.StartPickingTime,
        timezone,
      ).toISOString();
      updatedQueryParameters.StartPickingTime = startPickingTime;
    }
    if (updatedQueryParameters.StartProductionTime) {
      const startProductionTime = convertToUTC(
        updatedQueryParameters.StartProductionTime,
        timezone,
      ).toISOString();
      updatedQueryParameters.StartProductionTime = startProductionTime;
    }
    const orders = await this.fetchOrderData(updatedQueryParameters);
    const materials = [
      ...new Set(orders.map((order) => order.material)),
    ].filter(Boolean);
    const toStorageLocs = [
      ...new Set(orders.map((order) => order.toStorageLoc)),
    ].filter(Boolean);
    const fromStorageLocs = [
      ...new Set(orders.map((order) => order.fromStorageLoc)),
    ].filter(Boolean);
    const customerCodes = [
      ...new Set(orders.map((order) => order.customer)),
    ].filter(Boolean);
    const workcenterIds = [
      ...new Set(orders.map((order) => order.workCenterDescription)),
    ].filter(Boolean);

    const sapServer = await this.getSapServerByPlant(plantId);
    const [customers, workcenters, toStorageLocValues, fromStorageLocValues] =
      await Promise.all([
        this.getCustomersByCodes(
          customerCodes.filter((code): code is string => code !== undefined),
          sapServer.sapServer as string,
        ),
        this.getWorkcentersByIds({
          plant: Number(plantId),
          workcenterIds: workcenterIds.filter(
            (id): id is string => id !== undefined,
          ),
        }),
        this.getStorageLocationsByKeys(
          Number(plantId),
          materials,
          toStorageLocs.filter((loc): loc is string => loc !== undefined),
        ),
        this.getStorageLocationsByKeys(
          Number(plantId),
          materials,
          fromStorageLocs.filter((loc): loc is string => loc !== undefined),
        ),
      ]);
    const enrichedOrders = orders.map((order) => {
      const customer = customers?.find(
        (c) => c.customerCode === order.customer,
      );
      const workCenter = workcenters?.find(
        (wc) => wc.workcenterId === order.workCenterDescription,
      );

      // Find the corresponding storage bins based on location
      const toStorageBin =
        toStorageLocValues?.find(
          (bin) =>
            bin.materialId === order.material &&
            bin.storageLocationId === order.toStorageLoc,
        )?.storbin ?? '';
      const fromStorageBin =
        fromStorageLocValues?.find(
          (bin) =>
            bin.materialId === order.material &&
            bin.storageLocationId === order.fromStorageLoc,
        )?.storbin ?? '';

      return {
        ...order,
        customerDescription: customer?.name1 ?? '',
        fromStorageBin,
        toStorageBin,
        workCenter: order.workCenterDescription,
        workCenterDescription: workCenter?.description ?? '',
      };
    });
    const converter = new ShopOrderXmlConverter();

    const xmlResult = converter.convertToXml(enrichedOrders, timezone);
    return xmlResult;
  }

  public async fetchOrderData(
    requestDto: FilterDTO,
  ): Promise<Array<ShoporderResponseDTO>> {
    const serviceAppId = this.daprConfigService.orderApiAppId;
    const serviceMethod = `/buffer/getShopOrderList`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.POST,
      requestDto, // Send the DTO object as the body
    );
    if (response) {
      return response as Array<ShoporderResponseDTO>;
    }

    throw new Error('Invalid response from fetchOrderData');
  }

  public async getCustomersByCodes(
    customerCodes: Array<string>,
    sapServer: string,
  ): Promise<Array<CustomerResponseDTO> | undefined> {
    try {
      const serviceAppId = this.daprConfigService.shipmentApiAppId;
      const chunkedCustomerCodes = ShopOrderService.chunkArray(
        customerCodes,
        100,
      );
      const responses = await Promise.all(
        chunkedCustomerCodes.map((chunk) =>
          this.daprClient.invoker.invoke(
            serviceAppId,
            `customer/getCustomersByCodes`,
            HttpMethod.POST,
            {
              sapServer,
              customerCodes: chunk,
            },
          ),
        ),
      );
      return responses.flat() as Array<CustomerResponseDTO>;
    } catch (error) {
      AppLogger.error(`Failed to retrieve customers by codes`, error);
      return undefined;
    }
  }

  public async getWorkcentersByIds(
    workcenterIdsDto: WorkcenterIdsDTO,
  ): Promise<Array<WorkcenterResponseDTO> | undefined> {
    try {
      const chunkedWorkcenterIds = ShopOrderService.chunkArray(
        workcenterIdsDto.workcenterIds,
        100,
      );
      const responses = await Promise.all(
        chunkedWorkcenterIds.map((chunk) =>
          this.daprClient.invoker.invoke(
            this.daprConfigService.plantHierarchyApiAppId,
            `workcenter/getWorkcentersByIds`,
            HttpMethod.POST,
            { ...workcenterIdsDto, workcenterIds: chunk },
            {
              headers: {
                authorization: `Bearer ${process.env.TOKEN}`,
              },
            },
          ),
        ),
      );
      return responses.flat() as Array<WorkcenterResponseDTO>;
    } catch (error) {
      AppLogger.error(`Failed to retrieve workcenter details`, error);
      return undefined;
    }
  }

  public async getStorageLocationsByKeys(
    plant: number,
    materialIds: Array<string>,
    storageLocationIds: Array<string>,
  ): Promise<Array<CheckMaterialStorageLocationDto> | undefined> {
    const payload = {
      materialIds,
      plant,
      storageLocationIds,
    };
    try {
      const chunkedMaterialIds = ShopOrderService.chunkArray(materialIds, 100); // Adjust chunk size as needed
      const chunkedStorageLocationIds = ShopOrderService.chunkArray(
        storageLocationIds,
        100,
      ); // Adjust chunk size as needed
      const responses = await Promise.all(
        chunkedMaterialIds.flatMap((materialChunk) =>
          chunkedStorageLocationIds.map((storageChunk) =>
            this.daprClient.invoker.invoke(
              this.daprConfigService.masterApiAppId,
              `/material-storage-location/check`,
              HttpMethod.POST,
              {
                ...payload,
                materialIds: materialChunk,
                storageLocationIds: storageChunk,
              },
            ),
          ),
        ),
      );
      return responses.flat() as Array<CheckMaterialStorageLocationDto>;
    } catch (error) {
      AppLogger.error('Failed to fetch storage locations', error);
      return undefined;
    }
  }

  public async getFiltersSelections(
    plant: string,
  ): Promise<BufferFiltersSelectionsWithWorkcenterDiscriptionDTO> {
    try {
      const response = await this.daprClient.invoker.invoke(
        this.daprConfigService.orderApiAppId,
        `buffer/getFiltersSelections/${plant}`,
        HttpMethod.GET,
      );

      const dataWithoutWorkcenterDes = response as BufferFiltersSelectionsDTO;

      let enrichedWorkcenters: Array<WorkcenterResponseDTO> | undefined;
      let mappedWorkcenters: Array<{
        workcenter: string;
        description: string;
      }> = [];

      if (
        dataWithoutWorkcenterDes.workcenterList &&
        dataWithoutWorkcenterDes.workcenterList.length > 0
      ) {
        enrichedWorkcenters = await this.getWorkcentersByIds({
          plant: Number(plant),
          workcenterIds: dataWithoutWorkcenterDes.workcenterList,
        });

        mappedWorkcenters = dataWithoutWorkcenterDes.workcenterList.map(
          (wcId) => {
            const enriched = enrichedWorkcenters?.find(
              (wc) => wc.workcenterId === wcId,
            );
            return {
              workcenter: wcId,
              description: enriched?.description ?? 'Unknown',
            };
          },
        );
      }

      const enrichedResponse: BufferFiltersSelectionsWithWorkcenterDiscriptionDTO =
        {
          ...dataWithoutWorkcenterDes,
          workcenterList: mappedWorkcenters,
        };

      return enrichedResponse;
    } catch (error) {
      AppLogger.error(`Failed to retrieve buffer filters selections`, error);
      throw new InternalServerErrorException(
        'Error retrieving buffer filters selections',
      );
    }
  }

  public async getBufferDataByCriteria(
    plant: string,
    criteria: BufferCriteriaDTO & { page?: number; pageSize?: number },
  ): Promise<PaginatedBufferResponseDto> {
    try {
      const queryParameters = new URLSearchParams();

      for (const [key, value] of Object.entries(criteria)) {
        if (Array.isArray(value)) {
          for (const item of value) queryParameters.append(key, item);
        } else {
          queryParameters.append(key, value as string);
        }
      }
      const response = await this.daprClient.invoker.invoke(
        this.daprConfigService.orderApiAppId,
        `buffer/getBufferDataByCriteria/${plant}?${queryParameters.toString()}`,
        HttpMethod.GET,
      );
      return response as PaginatedBufferResponseDto;
    } catch (error) {
      AppLogger.error(`Failed to retrieve buffer data`, error);
      throw new InternalServerErrorException('Error retrieving buffer data');
    }
  }

  // Develope api to get plant by id from plt-hry
  public async getPlantById(plantId: number): Promise<Plant> {
    try {
      const response = await this.daprClient.invoker.invoke(
        this.daprConfigService.plantHierarchyApiAppId,
        `plant/getPlantById/${plantId}`,
        HttpMethod.GET,
      );
      return response as Plant;
    } catch (error) {
      AppLogger.error(`Failed to retrieve plant details`, error);
      throw new InternalServerErrorException('Error retrieving plant details');
    }
  }
}

