import { KANBAN_VALIDATION_SCHEMA } from '../config/kanban-validation-schema';
import { CreateBufferTableDto } from '../dtos/buffer-table.dto';
import { Context } from '../interfaces/validate-assign.interface.dto';
import { validateAndAssign } from './validate-and-assign';

/**
 * Validates that an end date is not earlier than its corresponding start date.
 * @param errorLog - Mutable list where validation messages are appended.
 * @param createBufferTableDto - Target DTO containing the date values to compare.
 * @param startField - DTO key for the start date field.
 * @param endField - DTO key for the end date field.
 */
function validateStartEndDateRange(
  errorLog: Array<string>,
  createBufferTableDto: Partial<CreateBufferTableDto>,
  startField: keyof CreateBufferTableDto,
  endField: keyof CreateBufferTableDto,
): void {
  const startValue = createBufferTableDto[startField];
  const endValue = createBufferTableDto[endField];

  if (!(startValue instanceof Date) || !(endValue instanceof Date)) {
    return;
  }

  if (endValue.getTime() < startValue.getTime()) {
    errorLog.push(
      `${String(endField)} must be greater than or equal to ${String(startField)}`,
    );
  }
}

/**
 * Executes all validations for a Kanban item using the centralized schema.
 * This replaces repetitive validateAndAssign calls with a single loop-based approach.
 * @param errorLog - Array to collect validation errors
 * @param validationContext - Context containing all required data for validation
 */
export async function executeKanbanValidations(
  errorLog: Array<string>,
  validationContext: Context,
): Promise<void> {
  for (const config of KANBAN_VALIDATION_SCHEMA) {
    const value =
      config.kanbanDataKey === 'plantId.number'
        ? validationContext.plantId
        : validationContext.kanbanData[config.kanbanDataKey];

    await validateAndAssign(
      {
        errorLog,
        field: config.field as keyof CreateBufferTableDto,
        maxlength: config.maxlength,
        type: config.type,
        value,
      },
      validationContext,
    );
  }
  validateStartEndDateRange(
    errorLog,
    validationContext.createBufferTableDto,
    'startPickingDatetime',
    'endPickingDatetime',
  );

  validateStartEndDateRange(
    errorLog,
    validationContext.createBufferTableDto,
    'startProductionDatetime',
    'endProductionDatetime',
  );
}

type FieldValue = string | null | undefined | Date | number;

export const isValueEmptyOrInvalid = (value: FieldValue): boolean => {
  return (
    value === null || value === '' || value === 'NaN' || value === undefined
  );
};

import { CreateBufferTableDto } from '../dtos/buffer-table.dto';
import { KanbanData } from '../interfaces/kanban-data.interface.dto';
import { EccLocationService } from '../sub-services/ecc-locations.service';
import { MaterialService } from '../sub-services/material.service';

type FieldValue = string | null | undefined | Date | number;

export const handleBatchField = async (
  field: keyof CreateBufferTableDto,
  value: FieldValue,
  kanbanData: KanbanData,
  plantId: number,
  errorLog: Array<string>,
  createBufferTableDto: CreateBufferTableDto,
  materialService: MaterialService,
  eccLocationService: EccLocationService,
): Promise<void> => {
  const isBatchempty = !value;

  if (!isBatchempty) {
    Object.assign(createBufferTableDto, { batch: value });
    return;
  }

  try {
    const bbbModeResponse = await materialService.getMaterialGroupAndMode(
      kanbanData.MaterialNumber ?? '',
      plantId,
    );
    const { bbbMode } = bbbModeResponse as { bbbMode: FieldValue };

    // If bbbMode is not '400', exit the function early
    if (bbbMode !== '400') {
      return;
    }
    try {
      const eccLocationAndStockResponse =
        await eccLocationService.getEccLocationAndPoolStock(
          plantId,
          kanbanData.SourceLocation ?? '',
        );
      const { poolstock } = eccLocationAndStockResponse as {
        poolstock: boolean;
      };

      if (poolstock) {
        Object.assign(createBufferTableDto, { batch: value });
      } else {
        errorLog.push(
          `Batch is empty, bbbMode is 400 and poolstock is 0 for material ${kanbanData.MaterialNumber}`,
        );
      }
    } catch {
      errorLog.push(
        `Storage location ${kanbanData.SourceLocation} not found or mismatch in ecc_location.`,
      );
    }
  } catch {
    // Optionally handle the error or leave empty
  }
};

import { CreateBufferTableDto } from '../dtos/buffer-table.dto';
import { CustomerService } from '../sub-services/customer.service';

export const handleCustomerField = async (
  value: string,
  errorLog: Array<string>,
  createBufferTableDto: CreateBufferTableDto,
  customerService: CustomerService,
): Promise<void> => {
  const isCustomerEmpty = !value;

  if (!isCustomerEmpty) {
    try {
      const customerResponse = (await customerService.getCustomerByCode(
        value,
      )) as {
        customerCode: string;
      };

      if (customerResponse?.customerCode) {
        Object.assign(createBufferTableDto, { customer: value });
      } else {
        errorLog.push(`Customer ${value} does not exist`);
      }
    } catch {
      errorLog.push(`Customer ${value} does not exist`);
    }
  }
};

