export const handleDeleteAction = (
  field: keyof CreateBufferTableDto,
  value: FieldValue,
  maxLength: number,
  errorLog: Array<string>,
  createBufferTableDto: CreateBufferTableDto,
): void => {
  if (field === 'orderId') {
    if (
      value === null ||
      value === '' ||
      value === undefined ||
      (value?.toString()?.length ?? 0) > maxLength
    ) {
      errorLog.push(
        `${field} cannot be null or wrong format for DELETE action`,
      );
    } else {
      Object.assign(createBufferTableDto, { orderId: value });
    }
  }
};

// Handle-delivery-number-field.ts
import { CreateBufferTableDto } from '../dtos/buffer-table.dto';
import { KanbanData } from '../interfaces/kanban-data.interface.dto';
import { OutbandService } from '../sub-services/outband.service';

type FieldValue = string | null | undefined | Date | number;
export const handleDeliveryNumberField = async (
  field: keyof CreateBufferTableDto,
  value: FieldValue,
  errorLog: Array<string>,
  createBufferTableDto: CreateBufferTableDto,
  kanbanData: KanbanData,
  plantId: number,
  outbandService: OutbandService,
  mandatoryDatesFromPreactor: boolean,
): Promise<void> => {
  const isDeliveryNumberEmpty = !value;
  const isTPANumberEmpty = !kanbanData.TPANumber;

  // Validation for DeliveryNumber and TPANumber mutual exclusivity
  if (
    (isDeliveryNumberEmpty && !isTPANumberEmpty) ||
    (!isDeliveryNumberEmpty && isTPANumberEmpty)
  ) {
    errorLog.push(`Both TPANumber and DeliveryNumber cannot be null or empty`);
    return;
  }

  // Check if both DeliveryNumber and TPANumber are provided
  if (!isDeliveryNumberEmpty && !isTPANumberEmpty) {
    try {
      const hdStatusResponse = await outbandService.getHdStatus(
        plantId,
        kanbanData.DeliveryNumber ?? '',
        kanbanData.MaterialNumber ?? '',
      );

      if (!hdStatusResponse) {
        errorLog.push(`DeliveryNumber: ${value} not found for this material`);
        return;
      }

      const { hdStatus } = hdStatusResponse as { hdStatus: string };
      const closedStatuses = ['CLOSEDSAP', 'CLOSEDMII', 'PICKCLOSED'];

      // Handle closed delivery statuses
      if (closedStatuses.includes(hdStatus)) {
        errorLog.push(
          `DeliveryNumber: ${value} for KANBAN: ${kanbanData.OrderID} has status: ${hdStatus}`,
        );
      }
      // Check mandatory dates when the flag is active
      else if (
        mandatoryDatesFromPreactor &&
        (!kanbanData.TruckDepartureDateTime ||
          !kanbanData.EndPreparationDateTime)
      ) {
        errorLog.push(
          `TruckDepartureDateTime and EndPreparationDateTime are mandatory for DeliveryNumber: ${value} when the flag mandatoryDatesFromPreactor is activated`,
        );
      }
    } catch {
      errorLog.push(`DeliveryNumber: ${value} not found for this material`);
    }

    // Assign the field value to the DTO
    Object.assign(createBufferTableDto, { deliveryNumber: value });
  }
};

import { CreateBufferTableDto } from '../dtos/buffer-table.dto';
import { KanbanData } from '../interfaces/kanban-data.interface.dto';
import { CustomerService } from '../sub-services/customer.service';
import { EccLocationService } from '../sub-services/ecc-locations.service';
import { MaterialService } from '../sub-services/material.service';
import { OutbandService } from '../sub-services/outband.service';
import { WorkcenterService } from '../sub-services/workcenter.service';
import { isValueEmptyOrInvalid } from './field-check';
import { handleBatchField } from './handle-batch-fields';
import { handleCustomerField } from './handle-customer-field';
import { handleDeliveryNumberField } from './handle-delivery-number-field';
import { handleMandatoryFields } from './handle-mandatory-fields';
import { handleProductionLineField } from './handle-production-line-field';
import { handleStorageLocationField } from './handle-storage-location-fields';
import { assignValueByType } from './value-format';

interface ValidationServices {
  materialService: MaterialService;
  eccLocationService: EccLocationService;
  customerService: CustomerService;
  outbandService: OutbandService;
  workcenterService: WorkcenterService;
}

interface ValidationParameters {
  field: keyof CreateBufferTableDto;
  value: string | null | undefined | Date | number;
  type: string;
  maxlength: number;
  errorLog: Array<string>;
  createBufferTableDto: CreateBufferTableDto;
  kanbanData: KanbanData;
  plantId: number;
  plantInfo: { timezone: string };
  mandatoryDatesFromPreactor: boolean;
  services: ValidationServices;
}

export const handleFieldValidation = async ({
  field,
  value,
  type,
  maxlength,
  errorLog,
  createBufferTableDto,
  kanbanData,
  plantId,
  plantInfo,
  mandatoryDatesFromPreactor,
  services,
}: ValidationParameters): Promise<void> => {
  // Validate empty or invalid value for mandatory fields
  if (isValueEmptyOrInvalid(value)) {
    handleMandatoryFields(field, errorLog);
  }

  // Process specific fields with their respective handlers
  switch (field) {
    case 'batch': {
      await handleBatchField(
        field,
        value,
        kanbanData,
        plantId,
        errorLog,
        createBufferTableDto,
        services.materialService,
        services.eccLocationService,
      );
      break;
    }
    case 'customer': {
      await handleCustomerField(
        value as string,
        errorLog,
        createBufferTableDto,
        services.customerService,
      );
      break;
    }
    case 'sourceLocation':
    case 'destinationLocation': {
      await handleStorageLocationField(
        field,
        value as string,
        errorLog,
        createBufferTableDto,
        plantId,
        kanbanData.MaterialNumber ?? '',
        services.eccLocationService,
      );
      break;
    }
    case 'deliveryNumber': {
      await handleDeliveryNumberField(
        field,
        value,
        errorLog,
        createBufferTableDto,
        kanbanData,
        plantId,
        services.outbandService,
        mandatoryDatesFromPreactor,
      );
      break;
    }
    case 'productionLine': {
      await handleProductionLineField(
        field,
        value as string,
        errorLog,
        createBufferTableDto,
        plantId,
        services.workcenterService,
      );
      break;
    }
    default: {
      assignValueByType(
        field,
        value,
        type,
        maxlength,
        createBufferTableDto,
        errorLog,
        plantInfo,
      );
    }
  }
};

