import * as xml2js from 'xml2js';
import { RowDTO } from '../interfaces/row.dto';
import { SoapKeys } from '../interfaces/soap-keys.dto';
/**
 *
 * @param responseRows - An array of rows, each containing action type, error, order ID, and status.
 * @returns A string representing the SOAP response XML.
 */
export function buildSoapResponse(responseRows: Array<RowDTO>): string {
  const builder = new xml2js.Builder({
    rootName: 'soap:Envelope',
    xmldec: { encoding: 'utf8', version: '1.0' },
  });

  const soapResponse = {
    $: {
      [SoapKeys.XMLNS_SOAP]: 'http://schemas.xmlsoap.org/soap/envelope/',
      [SoapKeys.XMLNS_XSD]: 'http://www.w3.org/2001/XMLSchema',
      [SoapKeys.XMLNS_XSI]: 'http://www.w3.org/2001/XMLSchema-instance',
    },
    [SoapKeys.SOAP_BODY]: {
      [SoapKeys.XACUTE_RESPONSE]: {
        $: { xmlns: 'http://www.sap.com/xMII' },
        [SoapKeys.ROWSET]: {
          [SoapKeys.ROW]: responseRows.map((row) => ({
            [SoapKeys.ACTION_TYPE]: row.ACTION_TYPE,
            [SoapKeys.ERROR]: row.ERROR || '---',
            [SoapKeys.ORDER_ID]: row.ORDER_ID,
            [SoapKeys.STATUS]: row.STATUS,
          })),
        },
      },
    },
  };

  return builder.buildObject(soapResponse);
}

