export const validateAndAssign = async (
  validationContext: ValidationContext,
  context: Context,
): Promise<void> => {
  const { field, value, maxlength, errorLog } = validationContext;
  const {
    createBufferTableDto,
    mandatoryDatesFromPreactor,
    kanbanData,
    plantId,
    plantInfo,
    services,
  } = context;

  await (createBufferTableDto.actionType === 'Deletion'
    ? handleDeleteAction(
        field,
        value,
        maxlength,
        errorLog,
        createBufferTableDto as CreateBufferTableDto,
      )
    : handleFieldValidation({
        createBufferTableDto: createBufferTableDto as CreateBufferTableDto,
        errorLog,
        field,
        kanbanData,
        mandatoryDatesFromPreactor,
        maxlength,
        plantId,
        plantInfo,
        services,
        type: validationContext.type,
        value,
      }));
};

import { DateTime } from 'luxon';
import { CreateBufferTableDto } from '../dtos/buffer-table.dto';

export const assignDateValue = (
  field: keyof CreateBufferTableDto,
  value: unknown, // Using `unknown` for stricter type checks
  createBufferTableDto: CreateBufferTableDto,
  errorLog: Array<string>,
  plantInfo: { timezone: string }, // Assuming plantInfo contains the timezone
): void => {
  let dateValue: DateTime | undefined;

  if (typeof value === 'string') {
    // Attempt to parse as ISO format
    dateValue = DateTime.fromISO(value, { zone: plantInfo.timezone });

    if (!dateValue.isValid) {
      // Attempt to parse as SQL format if ISO fails
      dateValue = DateTime.fromSQL(value, { zone: plantInfo.timezone });
    }

    if (dateValue.isValid) {
      // Convert to UTC JS Date and assign
      Object.assign(createBufferTableDto, {
        [field]: dateValue.toUTC().toJSDate(),
      });
    } else {
      errorLog.push(`${field} is not a valid date format`);
    }
  } else if (value instanceof Date) {
    // Handle Date object input
    dateValue = DateTime.fromJSDate(value).setZone(plantInfo.timezone);

    if (dateValue.isValid) {
      Object.assign(createBufferTableDto, {
        [field]: dateValue.toUTC().toJSDate(),
      });
    } else {
      errorLog.push(`${field} is not a valid date format`);
    }
  } else {
    // Handle invalid input type
    errorLog.push(`${field} is not a valid date format`);
  }
};
export const assignNumberValue = (
  field: keyof CreateBufferTableDto,
  value: unknown,
  createBufferTableDto: CreateBufferTableDto,
  errorLog: Array<string>,
): void => {
  const numberValue = Number(value);
  if (Number.isNaN(numberValue)) {
    errorLog.push(`${field} is not a valid number format`);
    return;
  }
  Object.assign(createBufferTableDto, { [field]: numberValue });
};

/**
 * Assign quantity value with special handling for empty strings.
 * Empty strings are converted to null instead of 0.
 * This function ONLY applies to the 'quantity' field.
 * @param field - DTO field name expected to be 'quantity'.
 * @param value - Incoming raw quantity value from payload.
 * @param createBufferTableDto - Target DTO where the parsed value is assigned.
 * @param errorLog - Validation error collector.
 */
export const assignQuantityValue = (
  field: keyof CreateBufferTableDto,
  value: unknown,
  createBufferTableDto: CreateBufferTableDto,
  errorLog: Array<string>,
): void => {
  // Only apply special null conversion for quantity field
  if (field !== 'quantity') {
    return;
  }

  // Handle empty string or null → set to null in DB
  if (value === '' || value === null || value === undefined) {
    Object.assign(createBufferTableDto, { [field]: undefined });
    return;
  }

  // Try to convert to number
  const numberValue = Number(value);
  if (Number.isNaN(numberValue)) {
    errorLog.push(`${field} is not a valid number format`);
    return;
  }

  Object.assign(createBufferTableDto, { [field]: numberValue });
};

// Assign value based on type
export const assignValueByType = (
  field: keyof CreateBufferTableDto,
  value: unknown,
  type: string,
  maxlength: number,
  createBufferTableDto: CreateBufferTableDto,
  errorLog: Array<string>,
  plantInfo: { timezone: string },
): void => {
  if (type === 'date') {
    if (value !== undefined && value !== '' && value !== null) {
      assignDateValue(field, value, createBufferTableDto, errorLog, plantInfo);
    }
  } else if (type === 'number' && field === 'quantity') {
    // Use special quantity handler for null conversion
    assignQuantityValue(field, value, createBufferTableDto, errorLog);
  } else if (type === 'number') {
    assignNumberValue(field, value, createBufferTableDto, errorLog);
  } else if ((value?.toString()?.length ?? 0) > maxlength) {
    errorLog.push(`${field} exceeds maximum length of ${maxlength}`);
  } else {
    Object.assign(createBufferTableDto, {
      [field]: value,
    });
  }
};

