import { DaprClient, HttpMethod } from '@dapr/dapr';
import { Injectable, Scope } from '@nestjs/common';
import { CreateBufferTableDto } from '../dtos/buffer-table.dto';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';

@Injectable({ scope: Scope.REQUEST })
export class BufferService {
  private readonly daprClient: DaprClient;

  public constructor(
    private readonly urlApiConfigService: UrlApiConfigService,
  ) {
    this.daprClient = new DaprClient();
  }

  public async createBufferTable(
    createBufferTableDto: Array<CreateBufferTableDto>,
  ): Promise<unknown> {
    const { urlOrderApi } = this.urlApiConfigService;
    const serviceMethod = `buffer/insert`;
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    try {
      const response = await this.daprClient.invoker.invoke(
        urlOrderApi,
        serviceMethod,
        HttpMethod.POST,
        createBufferTableDto,
        options,
      );

      return response;
    } catch (error_) {
      throw new Error(`${error_.message}`);
    }
  }

  /**
   * Update an existing buffer entry by its ID.
   * Used during reprocess to update the buffer line with new validation results.
   * @param bufferId - The buffer entry ID to update
   * @param updateDto - The partial DTO with fields to update
   * @returns The update response
   */
  public async updateBufferEntryById(
    bufferId: number,
    updateDto: Partial<CreateBufferTableDto>,
  ): Promise<unknown> {
    const { urlOrderApi } = this.urlApiConfigService;
    const serviceMethod = `buffer/${bufferId}/reprocess-status`;
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };

    try {
      const response = await this.daprClient.invoker.invoke(
        urlOrderApi,
        serviceMethod,
        HttpMethod.PUT,
        updateDto,
        options,
      );
      return response;
    } catch (error_) {
      throw new Error(`${error_.message}`);
    }
