import { Injectable } from '@nestjs/common';
import { CreateBufferTableDto } from '../dtos/buffer-table.dto';
import { WkResponseDto } from '../dtos/wk-response.dto';
import { executeKanbanValidations } from '../helper-functions/execute-kanban-validations';
import { KanbanData } from '../interfaces/kanban-data.interface.dto';
import { RowDTO } from '../interfaces/row.dto';
import { WriteBackParameters } from '../interfaces/write-back-parameters.dto';
import { BufferService } from './buffer.service';
import { CustomerService } from './customer.service';
import { EccLocationService } from './ecc-locations.service';
import { MaterialService } from './material.service';
import { OutbandService } from './outband.service';
import { RescheduleWkService } from './reschedule-wk.service';
import { WkUpdateService } from './wk-update.service';
import { WorkcenterService } from './workcenter.service';
import { convertFromUTC } from '@/utils/date';

@Injectable()
export class KanbanItemService {
  private static applyUpdateResponse(
    updateResponse: Array<{
      orderID: string;
      statusCode: string;
      statusMessage: string;
    }>,
    bufferTableDtos: Array<Partial<CreateBufferTableDto>>,
    rowDtos: Array<RowDTO>,
    statusCode: { error: string; success: string; received: string },
  ): void {
    const fallbackUpdateErrorMessage = 'Technical error while updating on MII';
    for (const response of updateResponse) {
      if (response.orderID) {
        const bufferResult = bufferTableDtos.find(
          (result) => result.orderId === response.orderID,
        );
        if (bufferResult) {
          bufferResult.bufferStatus = response.statusCode;
          bufferResult.errorLog =
            response.statusCode === statusCode.error
              ? response.statusMessage
              : '';
        }
        rowDtos.push(
          new RowDTO(
            response.orderID,
            response.statusCode === statusCode.error
              ? statusCode.error
              : statusCode.success,
            response.statusMessage ?? '',
            'Rescheduling',
          ),
        );
      }
    }

    if (
      bufferTableDtos.length === 1 &&
      !bufferTableDtos[0].bufferStatus &&
      updateResponse.length > 0
    ) {
      const fallbackResponse = updateResponse[0];
      const firstBufferDto = bufferTableDtos[0];
      firstBufferDto.bufferStatus =
        fallbackResponse.statusCode === statusCode.error
          ? statusCode.error
          : statusCode.success;
      firstBufferDto.errorLog =
        fallbackResponse.statusCode === statusCode.error
          ? fallbackResponse.statusMessage || fallbackUpdateErrorMessage
          : '';
    }
  }

  private static transformResponseForWriteBack(
    response: unknown,
    timeZone: string,
  ): Array<KanbanData> {
    let jsonData: Array<WkResponseDto>;

    if (Buffer.isBuffer(response)) {
      jsonData = JSON.parse(response.toString()) as Array<WkResponseDto>;
    } else if (typeof response === 'string') {
      jsonData = JSON.parse(response) as Array<WkResponseDto>;
    } else if (Array.isArray(response)) {
      jsonData = response as Array<WkResponseDto>;
    } else if (response && typeof response === 'object') {
      jsonData = [response as WkResponseDto];
    } else {
      throw new TypeError('Unexpected response type');
    }

    const keyMapping: { [key in keyof WkResponseDto]?: string } = {
      actionType: 'action',
      endPickingDatetime: 'endPickingDateTime',
      endPreparationDatetime: 'endPreparationDateTime',
      endProductionDatetime: 'endProductionDateTime',
      launchDatetime: 'launchingDateTime',
      orderId: 'OrderID',
      productionLineUpstream: 'ProductionLineUPstream',
      startPickingDatetime: 'startPickingDateTime',
      startProductionDatetime: 'startProductionDateTime',
      tpaNumber: 'TPANumber',
      truckDepartureDatetime: 'truckDepartureDateTime',
      upstreamMaterial: 'upstreamMaterial',
    };

    const transformedData = jsonData.map((item) => {
      const convertedItem: {
        [key: string]: string | number | Date | null | undefined;
      } = {};

      for (const key of Object.keys(item)) {
        const typedKey = key as keyof WkResponseDto;
        const mappedKey = keyMapping[typedKey] ?? key;
        const capitalizedKey =
          mappedKey.charAt(0).toUpperCase() + mappedKey.slice(1);

        const value = item[typedKey];

        if (
          typedKey === 'truckDepartureDatetime' &&
          value &&
          (typeof value === 'string' || value instanceof Date)
        ) {
          convertedItem.TruckDepartureDateTime = convertFromUTC(
            value,
            timeZone,
          );
        } else if (
          typedKey === 'endPreparationDatetime' &&
          value &&
          (typeof value === 'string' || value instanceof Date)
        ) {
          convertedItem.EndPreparationDateTime = convertFromUTC(
            value,
            timeZone,
          );
        } else if (
          typedKey === 'startProductionDatetime' &&
          value &&
          (typeof value === 'string' || value instanceof Date)
        ) {
          convertedItem.StartProductionDateTime = convertFromUTC(
            value,
            timeZone,
          );
        } else {
          convertedItem[capitalizedKey] = value;
        }
      }

      convertedItem['Kanban_type'] = 'WK';

      return convertedItem as KanbanData;
    });
    return transformedData;
  }

  private readonly statusCode = {
    error: 'ERROR',
    failure: 'FAILURE',
    received: 'RECEIVED',
    success: 'SUCCESS',
  };

  private readonly errorDelimiter = '; ';

  public constructor(
    private readonly bufferService: BufferService,
    private readonly materialService: MaterialService,
    private readonly eccLocationService: EccLocationService,
    private readonly customerService: CustomerService,
    private readonly outbandService: OutbandService,
    private readonly workcenterService: WorkcenterService,
    private readonly wkUpdateService: WkUpdateService,
  ) {}

  private async buildReprocessWriteBackParameters(
    response: unknown,
    plantId: number,
    timeZone: string,
  ): Promise<WriteBackParameters> {
    const transformedData = KanbanItemService.transformResponseForWriteBack(
      response,
      timeZone,
    );

    const transformedWithBbbMode = await Promise.all(
      transformedData.map(async (item) => {
        let bbbMode = '';

        try {
          const bbbModeResponse =
            (await this.materialService.getMaterialGroupAndMode(
              item.MaterialNumber ?? '',
              plantId,
            )) as { bbbMode: string; [key: string]: unknown };
          bbbMode = bbbModeResponse.bbbMode ?? '';
        } catch {
          bbbMode = '';
        }

        return {
          ...item,
          bbbMode,
        };
      }),
    );

    return RescheduleWkService.buildWriteBackParameters(
      transformedWithBbbMode,
      plantId,
    );
  }

  public async processKanbanItem(
    kanbanData: KanbanData,
    plantId: number,
    plantInfo: { timezone: string },
    mandatoryDatesFromPreactor: boolean,
  ): Promise<RowDTO> {
    const errorLog: Array<string> = [];
    const createBufferTableDto: Partial<CreateBufferTableDto> = {};
    const services = {
      customerService: this.customerService,
      eccLocationService: this.eccLocationService,
      materialService: this.materialService,
      outbandService: this.outbandService,
      workcenterService: this.workcenterService,
    };

    // Execute all validations using centralized schema
    await executeKanbanValidations(errorLog, {
      createBufferTableDto,
      kanbanData,
      mandatoryDatesFromPreactor,
      plantId,
      plantInfo,
      services,
    });

    // Set bufferStatus and store error log
    if (createBufferTableDto.bufferStatus) {
      createBufferTableDto.bufferStatus =
        errorLog.length > 0 ? this.statusCode.error : this.statusCode.success;
    } else {
      createBufferTableDto.bufferStatus =
        errorLog.length > 0 ? this.statusCode.error : this.statusCode.received;
    }
    createBufferTableDto.errorLog = errorLog.join(this.errorDelimiter);

    try {
      const bufferDtos = Array.isArray(createBufferTableDto)
        ? (createBufferTableDto as Array<CreateBufferTableDto>)
        : ([createBufferTableDto] as Array<CreateBufferTableDto>);
      await this.bufferService.createBufferTable(bufferDtos);
    } catch (error) {
      errorLog.push(`Error in createBufferTable: ${error.message}`);
      createBufferTableDto.bufferStatus = this.statusCode.error;
    }

    return new RowDTO(
      kanbanData.OrderID,
      createBufferTableDto.bufferStatus === this.statusCode.error
        ? this.statusCode.failure
        : this.statusCode.success,
      errorLog.join(this.errorDelimiter),
      kanbanData.Action,
    );
  }

  /**
   * Reprocess a kanban item: run the same validations as processKanbanItem
   * but UPDATE the existing buffer entry instead of creating a new one.
   * @param kanbanData - The kanban data rebuilt from the buffer line
   * @param plantId - The plant ID
   * @param plantInfo - Plant info with timezone
   * @param plantInfo.timezone - The timezone of the plant
   * @param mandatoryDatesFromPreactor - Flag for mandatory dates
   * @param bufferId - The existing buffer entry ID to update
   * @returns The result RowDTO
   */
  public async reprocessKanbanItem(
    kanbanData: KanbanData,
    plantId: number,
    plantInfo: { timezone: string },
    mandatoryDatesFromPreactor: boolean,
    bufferId: number,
  ): Promise<RowDTO> {
    const errorLog: Array<string> = [];
    const createBufferTableDto: Partial<CreateBufferTableDto> = {};
    const services = {
      customerService: this.customerService,
      eccLocationService: this.eccLocationService,
      materialService: this.materialService,
      outbandService: this.outbandService,
      workcenterService: this.workcenterService,
    };

    const validationContext = {
      createBufferTableDto,
      kanbanData,
      mandatoryDatesFromPreactor,
      plantId,
      plantInfo,
      services,
    };
    // Execute all validations using centralized schema
    await executeKanbanValidations(errorLog, validationContext);

    // Determine buffer status based on validation results
    // For reprocess: SUCCESS if WK update succeeds, otherwise ERROR
    if (
      errorLog.length === 0 &&
      createBufferTableDto.actionType === 'Rescheduling'
    ) {
      try {
        const writeBackParameters =
          await this.buildReprocessWriteBackParameters(
            kanbanData,
            plantId,
            plantInfo.timezone,
          );
        const updateResponse =
          await this.wkUpdateService.updateWK(writeBackParameters);

        if (Array.isArray(updateResponse) && updateResponse.length > 0) {
          KanbanItemService.applyUpdateResponse(
            updateResponse,
            [createBufferTableDto],
            [],
            {
              error: this.statusCode.error,
              success: this.statusCode.success,
              received: this.statusCode.received,
            },
          );

          if (createBufferTableDto.bufferStatus === this.statusCode.error) {
            errorLog.push(
              createBufferTableDto.errorLog ||
                'Technical error while updating on MII',
            );
          } else {
            createBufferTableDto.bufferStatus = this.statusCode.success;
          }
        } else {
          errorLog.push('Technical error while updating on MII');
          createBufferTableDto.bufferStatus = this.statusCode.error;
        }
      } catch (error) {
        errorLog.push(
          `Technical error while updating on MII: ${error.message}`,
        );
        createBufferTableDto.bufferStatus = this.statusCode.error;
      }
    } else {
      createBufferTableDto.bufferStatus =
        errorLog.length > 0 ? this.statusCode.error : this.statusCode.received;
    }

    createBufferTableDto.errorLog = errorLog.join(this.errorDelimiter);

    // Reset NEO fields so the order re-enters the normal integration flow
    createBufferTableDto.neoStatus = null;
    createBufferTableDto.neoIntegrationTime = null;
    // UPDATE the existing buffer entry instead of creating a new one
    try {
      await this.bufferService.updateBufferEntryById(
        bufferId,
        createBufferTableDto as CreateBufferTableDto,
      );
    } catch (error) {
      errorLog.push(`Error in updateBufferEntryById: ${error.message}`);
      createBufferTableDto.bufferStatus = this.statusCode.error;
    }

    return new RowDTO(
      kanbanData.OrderID,
      createBufferTableDto.bufferStatus === this.statusCode.error
        ? this.statusCode.failure
        : this.statusCode.success,
      errorLog.join(this.errorDelimiter),
      kanbanData.Action,
    );
  }
}

