import { RowDTO } from '../interfaces/row.dto';
import { WithdrawalKanbanRowDto } from '../interfaces/withdrawal-kanban-row.dto';
import { WriteBackParameters } from '../interfaces/write-back-parameters.dto';
import { BufferService } from './buffer.service';
import { CustomerService } from './customer.service';
import { EccLocationService } from './ecc-locations.service';
import { MaterialService } from './material.service';
import { OutbandService } from './outband.service';
import { PickingOrderService } from './picking-order.service';
import { WkUpdateService } from './wk-update.service';
import { WorkcenterService } from './workcenter.service';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class RescheduleWkService {
  public static async validateKanbanFields(
    kanbanData: KanbanData,
    plantId: number,
    plantInfo: { timezone: string },
    mandatoryDatesFromPreactor: boolean,
    createBufferTableDto: Partial<CreateBufferTableDto>,
    errorLog: Array<string>,
    services: {
      customerService: CustomerService;
      eccLocationService: EccLocationService;
      materialService: MaterialService;
      outbandService: OutbandService;
      workcenterService: WorkcenterService;
    },
  ): Promise<void> {
    // Use centralized validation schema and executor
    await executeKanbanValidations(errorLog, {
      createBufferTableDto,
      kanbanData,
      mandatoryDatesFromPreactor,
      plantId,
      plantInfo,
      services,
    });
  }

  private static extractOrderIds(kanbanData: Array<KanbanData>): Array<string> {
    return [
      ...new Set(
        kanbanData
          .filter(
            (item): item is KanbanData =>
              !!item &&
              typeof item === 'object' &&
              'OrderID' in item &&
              !!item.OrderID,
          )
          .map((item) => item.OrderID as string),
      ),
    ];
  }

  public static buildWriteBackParameters(
    kanbanWithBbbMode: Array<KanbanData & { bbbMode: string }>,
    plantId: number,
  ): WriteBackParameters {
    const builder = new xml2js.Builder({
      headless: true,
      renderOpts: { pretty: false },
    });
    const rowDto = new WithdrawalKanbanRowDto(kanbanWithBbbMode);
    const withdrawalKanbanXml = builder.buildObject(rowDto);

    return {
      contentType: '',
      inKanbanRequestXML: withdrawalKanbanXml,
      outputParameter: '',
      plant: plantId,
      session: '',
      transaction: '',
      xacuteLoginName: '',
      xacuteLoginPassword: '',
    };
  }

  private static applyUpdateResponse(
    updateResponse: Array<{
      orderID: string;
      statusCode: string;
      statusMessage: string;
    }>,
    bufferTableDtos: Array<Partial<CreateBufferTableDto>>,
    rowDtos: Array<RowDTO>,
    statusCode: { error: string; success: string; received: string },
  ): void {
    const fallbackUpdateErrorMessage = 'Technical error while updating on MII';
    const responseWithoutOrderId = updateResponse.find(
      (response) => !response.orderID,
    );

    if (responseWithoutOrderId) {
      const sharedErrorMessage =
        responseWithoutOrderId.statusMessage || fallbackUpdateErrorMessage;

      for (const bufferResult of bufferTableDtos) {
        bufferResult.bufferStatus = statusCode.error;
        bufferResult.errorLog = sharedErrorMessage;
      }
    }

    for (const response of updateResponse) {
      if (response.orderID) {
        const bufferResult = bufferTableDtos.find(
          (result) => result.orderId === response.orderID,
        );
        if (bufferResult) {
          bufferResult.bufferStatus = response.statusCode;
          bufferResult.errorLog =
            response.statusCode === statusCode.error
              ? response.statusMessage
              : '';
        }
        rowDtos.push(
          new RowDTO(
            response.orderID,
            response.statusCode === statusCode.error
              ? statusCode.error
              : statusCode.success,
            response.statusMessage ?? '',
            'Rescheduling',
          ),
        );
      } else {
        rowDtos.push(
          new RowDTO(
            '',
            statusCode.error,
            response.statusMessage || fallbackUpdateErrorMessage,
            'Rescheduling',
          ),
        );
      }
    }
  }

  private readonly logger = new AppLogger(RescheduleWkService.name);

  private readonly daprClient: DaprClient;

  private readonly activeHttpRequests = 0;

  public constructor(
    private readonly wkUpdateService: WkUpdateService,
    private readonly pickingOrderService: PickingOrderService,
    private readonly materialService: MaterialService,
    private readonly bufferService: BufferService,
    private readonly customerService: CustomerService,
    private readonly eccLocationService: EccLocationService,
    private readonly outbandService: OutbandService,
    private readonly workcenterService: WorkcenterService,
  ) {
    this.daprClient = new DaprClient();
  }

  private getValidationServices(): {
    customerService: CustomerService;
    eccLocationService: EccLocationService;
    materialService: MaterialService;
    outbandService: OutbandService;
    workcenterService: WorkcenterService;
  } {
    return {
      customerService: this.customerService,
      eccLocationService: this.eccLocationService,
      materialService: this.materialService,
      outbandService: this.outbandService,
      workcenterService: this.workcenterService,
    };
  }

  private async validateKanbanData(
    kanbanData: Array<KanbanData>,
    plantId: number,
    plantInfo: { timezone: string },
    mandatoryDatesFromPreactor: boolean,
  ): Promise<{
    kanbanBufferTableDtos: Array<Partial<CreateBufferTableDto>>;
    kanbanErrorLogs: Array<Array<string>>;
  }> {
    const services = this.getValidationServices();
    const validationPromises: Array<Promise<void>> = [];
    const kanbanBufferTableDtos: Array<Partial<CreateBufferTableDto>> = [];
    const kanbanErrorLogs: Array<Array<string>> = [];

    for (const kanban of kanbanData) {
      const kanbanErrorLog: Array<string> = [];
      const kanbanBufferTableDto: Partial<CreateBufferTableDto> = {};
      kanbanBufferTableDtos.push(kanbanBufferTableDto);
      kanbanErrorLogs.push(kanbanErrorLog);
      validationPromises.push(
        RescheduleWkService.validateKanbanFields(
          kanban,
          plantId,
          plantInfo,
          mandatoryDatesFromPreactor,
          kanbanBufferTableDto,
          kanbanErrorLog,
          services,
        ),
      );
    }
    await Promise.all(validationPromises);
    return { kanbanBufferTableDtos, kanbanErrorLogs };
  }

  private async getBbbMode(
    kanban: KanbanData,
    plantId: number,
  ): Promise<string> {
    try {
      const bbbModeResponse =
        (await this.materialService.getMaterialGroupAndMode(
          kanban.MaterialNumber ?? '',
          plantId,
        )) as { bbbMode: string; [key: string]: unknown };
      return bbbModeResponse.bbbMode;
    } catch {
      return '';
    }
  }

  private async buildRescheduleBuckets(
    kanbanData: Array<KanbanData>,
    filteredKanbanData: Array<KanbanData>,
    kanbanBufferTableDtos: Array<Partial<CreateBufferTableDto>>,
    kanbanErrorLogs: Array<Array<string>>,
    plantId: number,
    statusCode: { error: string; success: string; received: string },
    rowDtos: Array<RowDTO>,
    errorDelimiter: string,
  ): Promise<{
    bufferTableDtos: Array<Partial<CreateBufferTableDto>>;
    bufferWKNotExist: Array<Partial<CreateBufferTableDto>>;
    kanbanWithBbbMode: Array<KanbanData & { bbbMode: string }>;
  }> {
    const bufferTableDtos: Array<Partial<CreateBufferTableDto>> = [];
    const bufferWKNotExist: Array<Partial<CreateBufferTableDto>> = [];
    const kanbanWithBbbMode: Array<KanbanData & { bbbMode: string }> = [];

    const bbbModes = await Promise.all(
      kanbanData.map(async (kanban) => this.getBbbMode(kanban, plantId)),
    );

    for (const [index, kanban] of kanbanData.entries()) {
      const isInFiltered = filteredKanbanData.some(
        (k) => k.OrderID === kanban.OrderID,
      );
      const bbbMode = bbbModes[index];
      const bufferDto = kanbanBufferTableDtos[index];
      const errorLog = kanbanErrorLogs[index];

      if (errorLog.length > 0) {
        bufferDto.bufferStatus = statusCode.error;
        bufferDto.errorLog = errorLog.join(errorDelimiter);
        rowDtos.push(
          new RowDTO(
            kanban.OrderID ?? '',
            statusCode.error,
            errorLog.join(errorDelimiter),
            kanban.Action ?? 'Rescheduling',
          ),
        );
        bufferWKNotExist.push(bufferDto);
      } else {
        bufferDto.bufferStatus = bufferDto.bufferStatus
          ? statusCode.success
          : statusCode.received;
        bufferDto.errorLog = '';

        rowDtos.push(
          new RowDTO(
            kanban.OrderID ?? '',
            statusCode.success,
            '',
            kanban.Action ?? 'Rescheduling',
          ),
        );

        if (isInFiltered) {
          bufferDto.bufferStatus = statusCode.success;
          bufferTableDtos.push(bufferDto);
          kanbanWithBbbMode.push({
            ...kanban,
            bbbMode,
          });
        } else {
          bufferWKNotExist.push(bufferDto);
        }
      }
    }

    return { bufferTableDtos, bufferWKNotExist, kanbanWithBbbMode };
  }

  private async persistBufferRows(
    allBufferTableDtos: Array<Partial<CreateBufferTableDto>>,
    rowDtos: Array<RowDTO>,
    statusCode: { error: string; success: string; received: string },
  ): Promise<boolean> {
    try {
      await this.bufferService.createBufferTable(
        allBufferTableDtos as Array<CreateBufferTableDto>,
      );
      return true;
    } catch (error) {
      rowDtos.push(
        new RowDTO(
          '',
          statusCode.error,
          `Error in createBufferTable: ${error.message}`,
          'Rescheduling',
        ),
      );
      return false;
    }
  }

  public async handleReschedulingAction(
    kanbanData: Array<KanbanData>,
    plantId: number,
    plantInfo: { timezone: string },
    mandatoryDatesFromPreactor: boolean,
  ): Promise<Array<RowDTO>> {
    const statusCode = {
      error: 'ERROR',
      success: 'SUCCESS',
      received: 'RECEIVED',
    };
    const errorDelimiter = '; ';
    const rowDtos: Array<RowDTO> = [];

    try {
      const orderIds = RescheduleWkService.extractOrderIds(kanbanData);

      const orderExisting =
        await this.pickingOrderService.checkexistingPickingOrderList(
          orderIds,
          plantId,
        );

      const filteredKanbanData = kanbanData.filter(
        (kanban) => orderExisting[kanban.OrderID ?? ''],
      );
      const { kanbanBufferTableDtos, kanbanErrorLogs } =
        await this.validateKanbanData(
          kanbanData,
          plantId,
          plantInfo,
          mandatoryDatesFromPreactor,
        );
      const { bufferTableDtos, bufferWKNotExist, kanbanWithBbbMode } =
        await this.buildRescheduleBuckets(
          kanbanData,
          filteredKanbanData,
          kanbanBufferTableDtos,
          kanbanErrorLogs,
          plantId,
          statusCode,
          rowDtos,
          errorDelimiter,
        );
      if (kanbanWithBbbMode.length > 0) {
        const writeBackParameters =
          RescheduleWkService.buildWriteBackParameters(
            kanbanWithBbbMode,
            plantId,
          );

        const updateResponse =
          await this.wkUpdateService.updateWK(writeBackParameters);

        if (Array.isArray(updateResponse)) {
          RescheduleWkService.applyUpdateResponse(
            updateResponse,
            bufferTableDtos,
            rowDtos,
            statusCode,
          );
        }
      }
      const allBufferTableDtos = [...bufferTableDtos, ...bufferWKNotExist];
      const persistSucceeded = await this.persistBufferRows(
        allBufferTableDtos,
        rowDtos,
        statusCode,
      );
      if (!persistSucceeded) {
        return rowDtos;
      }

      return rowDtos;
    } catch (error) {
      rowDtos.push(
        new RowDTO(
          '',
          statusCode.error,
          `Technical error while updating on MII${error.message}`,
          'Rescheduling', // Or pass the action if available, otherwise use ''
        ),
      );
      return rowDtos;
    }
  }
}

import { HttpService } from '@nestjs/axios';
import { Injectable, Logger } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { firstValueFrom } from 'rxjs';
import { parseStringPromise } from 'xml2js'; // Importing the XML parser
import { ParametersDTO } from '../interfaces/parameters.dto';
import { RowType } from '../interfaces/row-type.interface.dto';
import { WriteBackParameters } from '../interfaces/write-back-parameters.dto';
import { PlantService } from './plant.service';
import { AppLogger } from '@/common/logger/app-logger';
import { ApiManagerConfigService } from '@/config/api-manager/api-manager.service';

@Injectable()
export class WkUpdateService {
  private readonly logger = new AppLogger(WkUpdateService.name);

  private readonly daprClient: DaprClient;

  private activeHttpRequests = 0;

  public constructor(
    private readonly customHttpService: HttpService,
    private readonly apiManagerConfigService: ApiManagerConfigService,
    private readonly plantService: PlantService,
  ) {
    this.daprClient = new DaprClient();
  }

  private async fetchSecret(
    secretStore: string,
    secretName: string,
  ): Promise<string> {
    try {
      const secretObject = await this.daprClient.secret.get(
        secretStore,
        secretName,
      );
      return Object.values(secretObject)[0];
    } catch (error_) {
      this.logger.error(
        `Error fetching secret ${secretName}: ${error_.message}`,
      );
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  public async updateWK(
    writeBackParameters: WriteBackParameters,
  ): Promise<
    Array<{ orderID: string; statusCode: string; statusMessage: string }>
  > {
    const STATUS_CODE = {
      errors: 'ERROR',
      success: 'SUCCESS',
    };
    const { plant, inKanbanRequestXML } = writeBackParameters;
    const { mainSecretStore, apiMgrSecretName, mesPasswordSecretName } =
      this.apiManagerConfigService;
    const [apiMgrKeyValue, mesPasswordValue] = await Promise.all([
      this.fetchSecret(mainSecretStore, apiMgrSecretName),
      this.fetchSecret(mainSecretStore, mesPasswordSecretName),
    ]);
    const formData = new URLSearchParams();
    formData.append('InKanbanRequestXML', inKanbanRequestXML.toString());
    const QUERY_TEMPLATE_UPDATE_WK_KANBAN =
      'SC_MES_API/INTERFACE/WKINTEGRATION/V1/XCT_UPDATE_WK_KANBAN';
    const plantinfo = (await this.plantService.getPlantById(plant)) as {
      plantLink: string;
    };
    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled();
    const apiManagerUrl = await this.apiManagerConfigService.apiManager();

    const illuminatorEndpointV1 = '/mii/illuminator/v1';
    const illuminatorEndpoint = '/XMII/Illuminator';

    const writeBackUrl = isApiManagerEnabled
      ? `${apiManagerUrl}${illuminatorEndpointV1}`
      : `${plantinfo.plantLink}${illuminatorEndpoint}`;

    try {
      this.activeHttpRequests += 1;
      const parameters = new ParametersDTO(
        plant, // InPlant
        'text/xml', // Content-type
        'ResultXML', // OutputParameter
        QUERY_TEMPLATE_UPDATE_WK_KANBAN, // QueryTemplate
        false, // Session
        await this.apiManagerConfigService.mesUserName(), // XacuteLoginName
        `${mesPasswordValue}`, // XacuteLoginPassword
      );

      Logger.log(
        `[updateWK] Starting HTTP call. Active requests: ${this.activeHttpRequests}`,
      );

      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, formData, {
          headers: {
            apiKey: apiMgrKeyValue,
          },
          params: parameters,
        }),
      );
      this.activeHttpRequests -= 1;
      Logger.log(
        `[updateWK] Finished HTTP call. Active requests: ${this.activeHttpRequests}`,
      );
      const jsonData = await parseStringPromise(response.data, {
        explicitArray: false,
      });

      // Handle Row as array or single object
      let rows = jsonData?.Rowsets?.Rowset?.Row;
      if (!Array.isArray(rows)) rows = [rows];

      // Define a type for the row objec
      // Map each row with your error handling logic
      return rows.map((row: RowType) => {
        const status = row?.Status;
        const errorMessage = row?.Message;
        const errorMessageMii = row?.Error;
        if (status !== STATUS_CODE.success) {
          return {
            orderID: row?.OrderID ?? '',
            statusCode: STATUS_CODE.errors,
            statusMessage:
              errorMessage && errorMessage.length > 150
                ? 'Technical error while updating on MII'
                : errorMessage || 'Technical error while updating on MII',
          };
        }
        if (status === STATUS_CODE.success) {
          if (!errorMessageMii || errorMessageMii === '---') {
            return {
              orderID: row?.OrderID ?? '',
              statusCode: STATUS_CODE.success,
              statusMessage: '',
            };
          }
          return {
            orderID: row?.OrderID ?? '',
            statusCode: STATUS_CODE.errors,
            statusMessage: errorMessageMii,
          };
        }
        return {
          orderID: row?.OrderID ?? '',
          statusCode: STATUS_CODE.success,
          statusMessage: '',
        };
      });
    } catch (error) {
      this.activeHttpRequests -= 1;
      Logger.error(
        `[updateWK] HTTP call failed. Active requests: ${this.activeHttpRequests} ${error.code}  ${error.message}`,
      );
      return [
        {
          orderID: '', // No row context in catch, so set to empty string
          statusCode: STATUS_CODE.errors,
          statusMessage: `Data integration is currently unavailable due to a temporary system communication issue. Please try again later.`,
        },
      ];
    }
  }
}

import { DaprClient, HttpMethod } from '@dapr/dapr';
import { Injectable, Scope } from '@nestjs/common';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';

@Injectable({ scope: Scope.REQUEST })
export class WorkcenterService {
  private readonly workcenterCache = new Map<string, unknown>();

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly urlApiConfigService: UrlApiConfigService,
  ) {
    this.daprClient = new DaprClient();
  }

  /**
   * Fetch workcenter details with caching.
   * @param plant Plant ID
   * @param workcenter Workcenter identifier
   * @returns Object containing workcenter details
   */
  public async getWorkcenter(
    plant: number,
    workcenter: string,
  ): Promise<unknown> {
    const cacheKey = `${plant}-${workcenter}`;

    // Check cache
    if (this.workcenterCache.has(cacheKey)) {
      const cachedValue = this.workcenterCache.get(cacheKey);
      if (cachedValue) {
        return cachedValue;
      }
    }

    // Fetch from service if not in cache
    const { urlPlanthryApi } = this.urlApiConfigService;
    const serviceMethodPlantConfig = `/workcenter/check/${plant}/${workcenter}`;
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };

    try {
      const response = await this.daprClient.invoker.invoke(
        urlPlanthryApi,
        serviceMethodPlantConfig,
        HttpMethod.GET,
        undefined,
        options,
      );

      this.workcenterCache.set(cacheKey, response);
      // Cache the result
      return response;
    } catch (error_) {
      throw new Error(
        `Failed to fetch the workcenter ${workcenter} for the plant ${plant}: ${error_.message}`,
      );
    }
  }
}

import { Injectable } from '@nestjs/common';
import * as xml2js from 'xml2js';
import { GeneralDataResponse } from '../interfaces/general-data-response.interface.dto';
import { ParsedSoapRequest } from '../interfaces/soap-request.interface.dto';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class XmlRequestHandlerService {
  public static extractGeneralData(
    parsedRequest: ParsedSoapRequest,
  ): GeneralDataResponse {
    const xacute = parsedRequest['soap:Envelope']['soap:Body']['XacuteRequest'];
    const generalDataX = xacute.InputParams['InRequestXML'];
    const generalData = generalDataX.Root.GeneralWKData;
    const plantId = Number(generalData.Plant);
    const kanbanDataArray = Array.isArray(generalDataX.Root.WithdrawalKanban)
      ? generalDataX.Root.WithdrawalKanban
      : [generalDataX.Root.WithdrawalKanban];

    return {
      generalData,
      kanbanDataArray,
      loginName: xacute.LoginName,
      loginPassword: xacute.LoginPassword,
      plantId,
    };
  }

  private readonly logger = new AppLogger(XmlRequestHandlerService.name);

  private readonly parser = new xml2js.Parser({ explicitArray: false });

  public async parseAndDecode(xmlBody: Buffer): Promise<ParsedSoapRequest> {
    try {
      const xmlString = xmlBody
        .toString('utf8')
        .replaceAll('&lt;', '<')
        .replaceAll('&gt;', '>');

      return await this.parser.parseStringPromise(xmlString);
    } catch (error_) {
      this.logger.error('Failed to parse XML input:', error_.message || error_);

      throw new Error('Invalid XML format. Parsing failed.');
    }
  }
}

import {
  Controller,
  HttpStatus,
  Param,
  ParseIntPipe,
  Post,
  Req,
  Res,
  UseFilters,
} from '@nestjs/common';

import {
  ApiBody,
  ApiOkResponse,
  ApiOperation,
  ApiParam,
  ApiResponse,
  ApiTags,
} from '@nestjs/swagger';
import { Request, Response } from 'express';
import { WkIntegrationService } from './wk-integration.service';
import { MesGenericErrorFilter } from '@/common/filters/mes-generic-error.filter';

@Controller('wk-integration')
export class WkIntegrationController {
  public constructor(
    private readonly wkIntegrationService: WkIntegrationService,
  ) {}
  /**
   *
   * @param request - The HTTP request object
   * @param kanbanData - The kanban data to be processed
   * @param materialService - Service for handling material-related operations
   * @param eccLocationService - Service for handling ECC location-related operations
   * @param customerService - Service for handling customer-related operations
   * @param outbandService - Service for handling outband-related operations
   * @param workcenterService - Service for handling workcenter-related operations
   * @param bufferService - Service for handling buffer-related operations
   * @param plantId - The ID of the plant
   * @param plantInfo - Information about the plant
   * @param plantInfo.timezone - The timezone of the plant
   * @param mandatoryDatesFromPreactor - Flag indicating if mandatory dates are from Preactor
   * @param pickingOrderService - Service for handling picking order operations
   * @param wkIntegrationService - Service for handling WK integration operations
   * @returns - The processed kanban item as a RowDTO
   */

  @Post('automatic-wk-integration-preactor')
  @ApiOperation({
    description:
      'Processes WK integration data from XML and returns the result as XML.',
    summary: 'Integrate WK Integration',
  })
  @ApiParam({
    description: 'HTTP request object containing the XML body for processing',
    name: 'request',
    required: true,
  })
  @ApiBody({
    description: 'XML data to be processed, provided in the request body',
    required: true,
    schema: {
      example: `<Root>
  <GeneralWKData>
    <Plant>1146</Plant>
  </GeneralWKData>
  <WithdrawalKanban>
    <Action>CREATE</Action>
    <Kanban_type>Wk</Kanban_type>
    <OrderID>MWKHND20241010003</OrderID>
    <ProductionLine>WC11102</ProductionLine>
    <ProductionLineUPstream/>
    <UpstreamMaterial>000000000000000000</UpstreamMaterial>
    <Batch></Batch>
    <Customer>0000000046</Customer>
    <DeliveryNumber>0078681967</DeliveryNumber>
    <TPANumber>test</TPANumber>
    <MaterialNumber>1302248TTF</MaterialNumber>
    <SourceLocation>PR20</SourceLocation>
    <DestinationLocation>OU10</DestinationLocation>
    <StartPickingDateTime>2024-03-30T09:45:00</StartPickingDateTime>
    <EndPickingDateTime>2024-04-30T10:50:00.000</EndPickingDateTime>
    <StartProductionDateTime>2024-03-30T00:00:00</StartProductionDateTime>
    <EndProductionDateTime>2024-04-17T10:30:00.000</EndProductionDateTime>
    <LaunchingDateTime>2024-03-30T01:00:00.000</LaunchingDateTime>
    <Quantity>2</Quantity>
    <EndPreparationDateTime>2024-04-30T10:30:00.000</EndPreparationDateTime>
    <TruckDepartureDateTime>2024-04-30T10:30:00.000</TruckDepartureDateTime>
  </WithdrawalKanban>
  </Root>`,
      type: 'string',
    },
  })
  @ApiOkResponse({
    description:
      'Returns the result of the WK integration process as an XML response.',
    schema: {
      example: `<ROWSETS>
  <ROW>
    <ORDER_ID>ORD123</ORDER_ID>
    <STATUS>SUCCESS</STATUS>
    <ERROR></ERROR>
    <ACTION_TYPE>Rescheduling</ACTION_TYPE>
  </ROW>
</ROWSETS>`,
      type: 'string',
    },
  })
  @ApiResponse({
    description: 'Internal server error when processing the XML data',
    status: 500,
  })
  public async createWKIntegrationPreactor(
    @Req() request: Request,
    @Res() response: Response,
  ): Promise<void> {
    const CONTENT_TYPE_XML = 'text/xml';

    try {
      const { xmlResponse, statusCode } =
        await this.wkIntegrationService.handleKanbanIntegrationRequest(
          request.body,
        );
      response.set('Content-Type', CONTENT_TYPE_XML);
      response.status(statusCode).send(xmlResponse);
    } catch (error) {
      console.error('Error processing request:', error);
      response.status(500).json({ error: 'Failed to process request' });
    }
  }

  @ApiTags('WK Integration') // Group the endpoint under a specific tag
  @ApiOperation({
    description:
      'Integrates WK data for a specific plant within a specified offset range.',
    summary: 'Integrate WK Data',
  })
  @ApiParam({
