  public async handleKanbanIntegrationRequest(
    requestBody: Buffer,
  ): Promise<{ xmlResponse: string; statusCode: number }> {
    try {
      const parsedRequest =
        await this.xmlRequestHandlerService.parseAndDecode(requestBody);

      const { plantId, kanbanDataArray, loginName, loginPassword } =
        XmlRequestHandlerService.extractGeneralData(parsedRequest);

      let mandatoryDatesFromPreactor = false;

      const plantInfo = (await this.plantService.getPlantById(plantId)) as {
        timezone: string;
      };

      try {
        const plantFlags = (await this.plantService.getPlantConfigFlags(
          plantId,
        )) as {
          blockNeoLogisticModification: boolean;
          mandatoryDatesFromPreactor: boolean;
          plant: number;
        };
        mandatoryDatesFromPreactor = plantFlags.mandatoryDatesFromPreactor;
      } catch (error_) {
        this.logger.error('Failed to get plant config flags:', error_);
      }

      const authValidator = await this.authService.validateUser(
        loginName,
        loginPassword,
      );

      if (!authValidator) {
        const xmlFaultResponse = buildSoapFaultResponse(
          'Unable to authenticate user',
        );
        return { xmlResponse: xmlFaultResponse, statusCode: 401 };
      }

      // Filtering data with Action property

      const creationItems: Array<KanbanData> = [];
      const reschedulingItems: Array<KanbanData> = [];

      for (const item of kanbanDataArray) {
        if (!!item && typeof item === 'object' && 'Action' in item) {
          if (item.Action === 'Rescheduling') {
            reschedulingItems.push(item);
          } else {
            // Pad MaterialNumber and UpstreamMaterial with leading zeros if they are all numeric
            if (item.MaterialNumber) {
              item.MaterialNumber = padNumericTo18Digits(item.MaterialNumber);
            }
            if (item.UpstreamMaterial) {
              item.UpstreamMaterial = padNumericTo18Digits(
                item.UpstreamMaterial,
              );
            }
            creationItems.push(item);
          }
        }
      }
      const reschedulingResponses = await ChunkProcessor.processInChunksArray(
        reschedulingItems,
        20,
        async (reschedulingRows: Array<KanbanData>) => {
          return this.rescheduleWkService.handleReschedulingAction(
            reschedulingRows,
            plantId,
            plantInfo,
            mandatoryDatesFromPreactor,
          );
        },
        (a: KanbanData, b: KanbanData) => {
          const dateA = a.LaunchingDateTime
            ? new Date(a.LaunchingDateTime).getTime()
            : Infinity;
          const dateB = b.LaunchingDateTime
            ? new Date(b.LaunchingDateTime).getTime()
            : Infinity;
          return dateA - dateB;
        },
        5,
      );
      const responseRows = await ChunkProcessor.processInChunks(
        creationItems,
        100,
        async (kanbanData: KanbanData) => {
          return this.kanbanItemService.processKanbanItem(
            kanbanData,
            plantId,
            plantInfo,
            mandatoryDatesFromPreactor,
          );
        },
      );
      let allResponseRows;

      if (reschedulingResponses && reschedulingResponses.length > 0) {
        const backgroundResponses = reschedulingItems.map((item) => {
          return new RowDTO(item.OrderID, 'SUCCESS', '', 'Rescheduling');
        });
        allResponseRows = [...responseRows, ...backgroundResponses];
      } else {
        allResponseRows = [...responseRows];
      }

      const xmlResponse = buildSoapResponse(allResponseRows);
      return { xmlResponse, statusCode: 201 };
    } catch (error_) {
      this.logger.error('Error in handleKanbanIntegrationRequest:', error_);
      const xmlFaultResponse = buildSoapFaultResponse(
        'An unexpected error occurred during Kanban integration.',
      );
      return { xmlResponse: xmlFaultResponse, statusCode: 500 };
    }
  }

