  public async fetchOrderStatusBatch(
    orders: Array<string>,
    plant: number,
  ): Promise<Array<unknown>> {
    const { urlOrderApi } = this.urlApiConfigService;
    const serviceMethod = `buffer/getOrderStatusBatch/${plant}`;

    try {
      // Process orders in batches of 1000
      const batchSize = 1000;
      const batchPromises: Array<Promise<Array<unknown>>> = [];

      for (let index = 0; index < orders.length; index += batchSize) {
        const batch = orders.slice(index, index + batchSize);

        const promise = this.daprClient.invoker
          .invoke(urlOrderApi, serviceMethod, HttpMethod.POST, {
            orderIds: batch,
          })
          .then((response) => response as Array<unknown>);

        batchPromises.push(promise);
      }

      const batchResults = await Promise.all(batchPromises);
      return batchResults.flat();
    } catch (error_) {
      throw new Error(`${error_.message}`);
    }
  }

