  public async fetchWkByTimeRange(
    plant: number,
    timeZone: string,
    offsetTo: number,
  ): Promise<{ orderIds: Array<string>; xmlData: string }> {
    const serviceAppId = this.urlApiConfigService.urlOrderApi;
    const serviceMethodSeqnum = `buffer/getWK/${plant}/${offsetTo}`;
    const builder = new xml2js.Builder({ rootName: 'Root' });

    try {
      // Fetch response from Dapr
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethodSeqnum,
        HttpMethod.GET,
      );
      if (!response) {
        throw new Error('No response from fetchWkByTimeRange');
      }

      let jsonData: Array<WkResponseDto>;

      // Parse the response based on its type
      if (Buffer.isBuffer(response)) {
        jsonData = JSON.parse(response.toString()) as Array<WkResponseDto>;
      } else if (typeof response === 'string') {
        jsonData = JSON.parse(response) as Array<WkResponseDto>;
      } else if (Array.isArray(response)) {
        jsonData = response as Array<WkResponseDto>;
      } else {
        throw new TypeError('Unexpected response type');
      }

      // Key mapping for transformation
      const keyMapping: { [key in keyof WkResponseDto]?: string } = {
        actionType: 'action',
        endPickingDatetime: 'endPickingDateTime',
        endPreparationDatetime: 'endPreparationDateTime',
        endProductionDatetime: 'endProductionDateTime',
        launchDatetime: 'launchingDateTime',
        orderId: 'OrderID',
        productionLineUpstream: 'ProductionLineUPstream',
        startPickingDatetime: 'startPickingDateTime',
        startProductionDatetime: 'startProductionDateTime',
        tpaNumber: 'TPANumber',
        truckDepartureDatetime: 'truckDepartureDateTime',
      };

      // Transform the response JSON according to the key mapping
      const transformedData = jsonData.map((item) => {
        const convertedItem: {
          [key: string]: string | number | Date | undefined;
        } = {};

        for (const key of Object.keys(item)) {
          const typedKey = key as keyof WkResponseDto;
          const mappedKey = keyMapping[typedKey] ?? key;

          // Capitalize the first letter of the key
          const capitalizedKey =
            mappedKey.charAt(0).toUpperCase() + mappedKey.slice(1);

          // Check for undefined truckDepartureDatetime before calling convertFromUTC
          if (typedKey === 'truckDepartureDatetime' && item[typedKey]) {
            convertedItem['TruckDepartureDateTime'] = convertFromUTC(
              item[typedKey],
              timeZone,
            );
          }
          // Check for undefined endPreparationDatetime before calling convertFromUTC
          if (typedKey === 'endPreparationDatetime' && item[typedKey]) {
            convertedItem['EndPreparationDateTime'] = convertFromUTC(
              item[typedKey],
              timeZone,
            );
          }
          // Check for undefined startProductionDatetime before calling convertFromUTC
          if (typedKey === 'startProductionDatetime' && item[typedKey]) {
            convertedItem['StartProductionDateTime'] = convertFromUTC(
              item[typedKey],
              timeZone,
            );
          }
          if (
            typedKey !== 'endPreparationDatetime' &&
            typedKey !== 'truckDepartureDatetime' &&
            typedKey !== 'startProductionDatetime'
          ) {
            // Copy other fields as-is without duplicates
            convertedItem[capitalizedKey] = item[typedKey];
          }
        }

        convertedItem['Kanban_type'] = 'WK';

        return convertedItem;
      });
      const dataToConvert = new WkDto(transformedData);
      // Build the XML
      const xmlData = builder.buildObject(dataToConvert);
      const orderIds = jsonData
        .map((item) => item.orderId)
        .filter((id): id is string => id !== undefined);
      return { orderIds, xmlData };
    } catch (error_) {
      this.logger.error(
        `Failed to fetch WK for plant ${plant} within the specified range: ${error_}`,
      );
      throw error_;
    }
  }

