  public async processWkData(plant: number): Promise<{
    action: string;
    customStatus: string;
    neoIntegrationTime: Date | undefined;
    orderId: string;
    statusCode: string;
    statusMessage: string;
  }> {
    const daprClient = new DaprClient();
    const { mainSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      mainSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      mainSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];
    const offsets = await this.getOffsets(plant);
    const { offsetTo } = offsets;
    // Get the plant information including the timezone
    const plantData = (await this.plantService.getPlantById(plant)) as Plant;
    // Exctract the timezone field and fallback to 'UTC' if timezone is undefined
    const timeZone = plantData.timezone ?? 'UTC';
    // Pass the timeZone as a new parameter to the fetchWkByTimeRange
    const { orderIds, xmlData } = await this.fetchWkByTimeRange(
      plant,
      timeZone,
      offsetTo,
    );
    if (orderIds.length > 0) {
      await this.updateBufferEntries(
        plant,
        orderIds,
        'RECEIVED',
        'IN_PROGRESS',
      );
    }
    const parameters = new KanbanParametersDto(
      plant,
      'text/xml',
      'ResultXML',
      'SC_MES_API/INTERFACE/WKINTEGRATION/V1/XCT_INTEGRATE_WK_KANBAN',
      false,
      await this.apiManagerConfigService.mesUserName(),
      mesPasswordValue,
    );
    const plantinfo = (await this.plantService.getPlantById(plant)) as {
      plantLink: string;
    };
    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled();
    const apiManagerUrl = await this.apiManagerConfigService.apiManager();

    const writeBackUrl = isApiManagerEnabled
      ? `${apiManagerUrl}/mii/illuminator/v1`
      : `${plantinfo.plantLink}/XMII/Illuminator`;

    // Form URL encoded data
    const formData = new URLSearchParams();

    formData.append('InKanbanRequestXML', xmlData);
    const headersDto = new RequestHeadersDto(
      'application/x-www-form-urlencoded', // ContentType
      apiMgrKeyValue, // ApiKey
    );
    this.logger.log(
      `apiMgrKeyValue (last 4 characters): ${apiMgrKeyValue.slice(Math.max(0, apiMgrKeyValue.length - 4))}`,
    );
    const timeOutProcessDataMilleSecond =
      (await this.wkIntegrationConfigService.timeoutProcessWkData()) * 1000;
    try {
      const response = await firstValueFrom(
        this.customHttpService
          .post(writeBackUrl, formData, {
            headers: { ...headersDto },
            maxBodyLength: Infinity,
            maxContentLength: Infinity,
            params: parameters,
          })
          .pipe(
            timeout(timeOutProcessDataMilleSecond), // Set timeout duration
            catchError((errors) => {
              this.logger.debug(`Error:${JSON.stringify(errors)}`);
              if (errors.name === 'TimeoutError') {
                return throwError(() => new Error('Request timed out'));
              }
              return throwError(() => errors);
            }),
          ),
      );

      // Parse XML to JSON
      const jsonData = await parseStringPromise(response.data, {
        explicitArray: false,
      });
      const rowset = jsonData?.Rowsets?.Rowset;
      if (!rowset?.Row) {
        return {
          action: '',
          customStatus: '',
          neoIntegrationTime: undefined,
          orderId: '',
          statusCode: 'NOT_FOUND',
          statusMessage: 'No WK Found',
        };
      }

      // Ensure Row is treated as an array (even if there is only one row)
      const rows = Array.isArray(rowset.Row) ? rowset.Row : [rowset.Row];

      // Map over all rows and return an array of processed results
      const result = rows.map((row: Row) => ({
        action: row.ACTION_TYPE,
        customStatus: row.CUSTOM_STATUS,
        neoIntegrationTime: row.NEO_INTEGRATION_TIME,
        orderId: row.ORDER_ID,
        statusCode: row.STATUS,
        statusMessage: row.ERROR,
      }));
      await this.updateBufferEntriesForListOfWKs(plant, result);
      return result;
    } catch (error_) {
      // Error handling
      if (error_.response) {
        this.logger.error('Error response data:', error_.response.data);
        this.logger.error('Error response headers:', error_.response.headers);
      } else if (error_.request) {
        this.logger.error('No response received:', error_.request);
      } else {
        this.logger.error('Error', error_.message);
      }
      if (
        error_.message === 'Request timed out' ||
        error_.code === 'ECONNREFUSED'
      ) {
        // Call the buffer reset service before returning
        await this.updateBufferEntries(
          plant,
          orderIds,
          'IN_PROGRESS',
          'RECEIVED',
        );
      }
      throw error_;
    }
  }

  public async getPickingOrdersByFilter(
    filterDto: PickingOrderFilterDTO,
  ): Promise<Array<PickingOrderDTO>> {
    try {
      const { urlOrderApi } = this.urlApiConfigService;
      const serviceMethod = `picking-order/getPickingOrdersByFilter`;
      try {
        const token = `Bearer ${process.env.TOKEN}`;
        const options = { headers: { authorization: token } };
        const response = await this.daprClient.invoker.invoke(
          urlOrderApi,
          serviceMethod,
          HttpMethod.POST,
          filterDto,
          options,
        );
