  public async updateMultipleOutboundsAsProcessed(
    plant: number,
    outbounds: Array<string>,
  ): Promise<Array<OutboundDeliveryDTO>> {
    const { urlShipApi } = this.urlApiConfigService;

    // Constructing the service endpoint
    const serviceMethod = `outbound-delivery/processed-outbounds`;

    // Prepare the body (DTO)
    const requestBody: UpdateOutboundsDto = {
      plant,
      outbounds,
    };

    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };
      // Make the invoker call with the correct HTTP method (PUT)
