      this.logger.error(
        `Failed to update outbounds as processed: ${error_.message}`,
      );
      return []; // Return an empty array in case of an error
    }
  }

  public async closeWk(
    plant: number,
  ): Promise<
    Array<{ orderId: string; statusCode: string; statusMessage: string }>
  > {
    try {
      const daprClient = new DaprClient();
      const { mainSecretStore } = this.apiManagerConfigService;
      const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
      const { mesPasswordSecretName } = this.apiManagerConfigService;

      const apiMgrKeyObject = await daprClient.secret.get(
        mainSecretStore,
        apiMgrKeySecretName,
      );
      const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];

      const mesPasswordObject = await daprClient.secret.get(
        mainSecretStore,
        mesPasswordSecretName,
      );
      const mesPasswordValue = Object.values(mesPasswordObject)[0];

      const plantinfo = (await this.plantService.getPlantById(plant)) as {
        plantLink: string;
      };

      const isApiManagerEnabled =
        await this.apiManagerConfigService.apiManagerEnabled();
      const apiManagerUrl = await this.apiManagerConfigService.apiManager();

      const writeBackUrl = isApiManagerEnabled
        ? `${apiManagerUrl}/mii/illuminator/v1`
        : `${plantinfo.plantLink}/XMII/Illuminator`;

      const outboundFilter: OutboundDeliveryFilterDTO = {
        hdStatus: ['CLOSEDSAP'],
        outputColumns: ['outbound'],
        plant,
        processed: false,
      };

      const outbounds = await this.getOutboundByFilter(outboundFilter);
      const allPickingOrders: Array<PickingOrderDTO> = [];
      if (outbounds?.length) {
        const outboundIds: Array<string> = outbounds.map((o) => o.outbound);

        const pickingOrderFilter: PickingOrderFilterDTO = {
          outbound: outboundIds,
          plant,
          customStatusToBeExcluded: ['CLOSED'],
          outputColumns: ['pickingOrderId'],
        };

        const pickingOrders =
          await this.getPickingOrdersByFilter(pickingOrderFilter);
        allPickingOrders.push(...pickingOrders);
      }
      const destinationStorageLocation =
        await this.getStorageLocationByPlantAndPoolstock(plant, true);
      const firstStorageLocation =
        destinationStorageLocation.storageLocationIds?.[0] || '';

      const allPickingOrderIds = allPickingOrders
        .map((order) => order.pickingOrderId)
        .join(';');

      const wkPayload = new WkPayloadDTO(
        plant,
        'NONE',
        firstStorageLocation,
        '',
        '',
      );
      const orderId = new URLSearchParams();
      orderId.append('OrderId', allPickingOrderIds);
      const headersDto = new RequestHeadersDto(
        'application/x-www-form-urlencoded', // ContentType
        apiMgrKeyValue, // ApiKey
      );
      const parameters = new WkParametersDto(
        plant,
        'text/xml',
        'ResultXML',
        'SC_MES_API/INTERFACE/WKINTEGRATION/V1/XCT_BATCH_UPDATE_WK_LOGISTIC_DATA',
        false,
        await this.apiManagerConfigService.mesUserName(),
        mesPasswordValue,
      );

      const newParameters = {
        ...parameters,
        ...wkPayload,
      };

      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, orderId, {
          headers: { ...headersDto },
          maxBodyLength: Infinity,
          maxContentLength: Infinity,
          params: newParameters,
        }),
      );

      const jsonData = await parseStringPromise(response.data, {
        explicitArray: false,
      });
      const rowset = jsonData?.Rowsets?.Rowset;
      const rows = Array.isArray(rowset.Row) ? rowset.Row : [rowset.Row];
      const result = rows.map((row: Element) => ({
        orderId: row.ORDER_ID,
        statusCode: row.STATUS,
        statusMessage: row.ERROR,
      }));
      const orderIds: Array<string> = result.map(
        (row: { orderId: string }) => row.orderId,
      );
      const ordersDto: GetOutboundsRequestDto = { orderIds };
      const outboundsForOrders = await this.getOutboundsbyorderIds(
        ordersDto,
        plant,
      );

      const allOutbounds: Array<string> = [];
      for (const { outbounds: innerOutbounds } of outboundsForOrders) {
        allOutbounds.push(...innerOutbounds);
      }

      await this.updateMultipleOutboundsAsProcessed(plant, allOutbounds);

      return result;
    } catch (error_) {
      if (error_.response) {
        this.logger.error('Error response data:', error_.response.data);
        this.logger.error('Error response headers:', error_.response.headers);
      } else if (error_.request) {
        this.logger.error('No response received:', error_.request);
      } else {
        this.logger.error('Error:', error_.message);
      }
      throw error_;
    }
  }
}

import {
  BadRequestException,
  Controller,
  Post,
  Req,
  Res,
} from '@nestjs/common';
import { ApiBody, ApiOperation, ApiResponse } from '@nestjs/swagger';
import { Response, Request } from 'express';
import * as xml2js from 'xml2js';
import { OrderDto } from '../wk-integration/dtos/order.dto';
import { SoapKeys } from '../wk-integration/interfaces/soap-keys.dto';
import { WkIntegrationService } from '../wk-integration/wk-integration.service';
import { AppLogger } from '@/common/logger/app-logger';
import { AppConfigInitialConfigService } from '@/config/app-config/app-config-initial-config.service';
import { AuthService } from '@/module/auth/auth.service';

@Controller('wsdl')
export class WsdlController {
  private readonly logger = new AppLogger(AppConfigInitialConfigService.name);

  public constructor(
    private readonly wkIntegrationService: WkIntegrationService,
    private readonly authService: AuthService,
  ) {}

  @Post('process-orders-preactor')
  @ApiOperation({
    description:
      'This endpoint processes orders from an XML input, fetching statuses for the given order IDs and returning the result in XML format.',
    summary: 'Process orders from XML input',
  })
  @ApiBody({
    description: 'XML input containing Plant and Order IDs.',
    required: true,
    schema: {
      example: `<Root>
    <GeneralWKData>
      <Plant>PLANT_CODE</Plant>
    </GeneralWKData>
    <WithdrawalKanban>
      <OrderID>ORDER_ID_1</OrderID>
      <OrderID>ORDER_ID_2</OrderID>
    </WithdrawalKanban>
  </Root>`,
      type: 'string',
    },
  })
  @ApiResponse({
    content: {
      applicationXml: {
        example: `<Rowsets>
    <Rowset>
      <Row>
        <Result>SUCCESS</Result>
        <ErrorLog></ErrorLog>
        <OrderID>ORDER_ID_1</OrderID>
        <Plant>PLANT_CODE</Plant>
        <Status>Active</Status>
      </Row>
      <Row>
        <Result>FAILURE</Result>
        <ErrorLog>ORDER_ID_2 does not exist</ErrorLog>
        <OrderID>ORDER_ID_2</OrderID>
        <Plant>PLANT_CODE</Plant>
        <Status></Status>
      </Row>
    </Rowset>
  </Rowsets>`,
      },
    },
    description: 'The processed orders result in XML format.',
    status: 200,
  })
  @ApiResponse({
    description: 'Invalid input XML: Missing Plant or OrderID data.',
    status: 400,
  })
  public async processOrdersPreactor(
    @Req() request: Request,
    @Res() response: Response,
  ): Promise<void> {
    const parser = new xml2js.Parser({ explicitArray: false });
    try {
      const xmlcoded = request.body.toString('utf8');
      const decodedXml = xmlcoded.replaceAll('&lt;', '<');
      const decodedXml2 = decodedXml.replaceAll('&gt;', '>');
      const result = await parser.parseStringPromise(decodedXml2);
      const authValidator = await this.authService.validateUser(
        result['soap:Envelope']['soap:Body']['XacuteRequest']['LoginName'],
        result['soap:Envelope']['soap:Body']['XacuteRequest']['LoginPassword'],
      );
      if (!authValidator) {
        const soapResponse = {
          $: {
            [SoapKeys.XMLNS_SOAP]: 'http://schemas.xmlsoap.org/soap/envelope/',
            [SoapKeys.XMLNS_XSD]: 'http://www.w3.org/2001/XMLSchema',
            [SoapKeys.XMLNS_XSI]: 'http://www-è.w3.org/2001/XMLSchema-instance',
          },
          [SoapKeys.SOAP_BODY]: {
            [SoapKeys.SOAP_FAULT]: {
              faultcode: 'soap:Client',
              faultstring: 'Unable to authenticate user',
            },
          },
        };
        const builder = new xml2js.Builder({
          rootName: 'soap:Envelope',
          xmldec: { encoding: 'utf8', version: '1.0' },
        });
        const xmlResponse = builder.buildObject(soapResponse);
        response.set('Content-Type', 'text/xml');
        response.status(401).send(xmlResponse);
      }

      // Extract actual request XML from InputParams
      const inRequestXml =
        result?.['soap:Envelope']?.['soap:Body']?.['XacuteRequest']?.[
          'InputParams'
        ]?.['DataXML'];

      const generalData = inRequestXml.Root.GeneralWKData;
      const plant = Number(generalData.Plant);
      // Ensure orderIds is an array and filter out empty values
      const orderIds: Array<string> = Array.isArray(
        inRequestXml.Root.WithdrawalKanban.OrderID,
      )
        ? inRequestXml.Root.WithdrawalKanban.OrderID
        : [inRequestXml.Root.WithdrawalKanban.OrderID];
      if (!plant || orderIds.length === 0) {
        throw new BadRequestException(
          'Invalid input XML: Missing Plant or OrderID data.',
        );
      }
      const results = await this.wkIntegrationService.fetchOrderStatusBatch(
        orderIds,
        plant,
      );
      const soapResponse = {
        $: {
          [SoapKeys.XMLNS_SOAP]: 'http://schemas.xmlsoap.org/soap/envelope/',
          [SoapKeys.XMLNS_XSD]: 'http://www.w3.org/2001/XMLSchema',
          [SoapKeys.XMLNS_XSI]: 'http://www.w3.org/2001/XMLSchema-instance',
        },
        [SoapKeys.SOAP_BODY]: {
          [SoapKeys.XACUTE_RESPONSE]: {
            $: { xmlns: 'http://www.sap.com/xMII' },
            [SoapKeys.ROWSET]: {
              [SoapKeys.ROW]: results.map(
                (order: {
                  status?: string;
                  orderId?: string;
                  plant?: string;
                }) => ({
                  [SoapKeys.STATUS]:
                    order?.status === undefined ? 'FAILURE' : 'SUCCESS',
                  [SoapKeys.ERROR]:
                    order?.status === undefined
                      ? `${order?.orderId} does not exist`
                      : '',
                  [SoapKeys.ORDER_ID]: order?.orderId ?? '',
                  [SoapKeys.PLANT]: order?.plant ?? '',
                  [SoapKeys.ORDER_STATUS]: order?.status ?? undefined,
                }),
              ),
            },
          },
        },
      };
      // Convert response to XML
      const builder = new xml2js.Builder({
        rootName: 'soap:Envelope',
        xmldec: { encoding: 'utf8', version: '1.0' },
      });
      const xmlResponse = builder.buildObject(soapResponse);
      const CONTENT_TYPE_XML = 'text/xml';
      // Send XML response with Content-Type set to application/xml
      response.set('Content-Type', CONTENT_TYPE_XML);
      response.status(201).send(xmlResponse);
    } catch (error) {
      console.error('Error processing XML:', error);
      response.status(500).json({ error: 'Failed to process XML data' });
    }
  }
}

