import { Logger } from '@nestjs/common';
import pLimit from 'p-limit';
import { RowDTO } from '@/module/wk-integration/interfaces/row.dto';

export class ChunkProcessor {
  public static async processInChunks<T>(
    items: Array<T>,
    concurrency: number,
    processItem: (item: T) => Promise<RowDTO>,
  ): Promise<Array<RowDTO>> {
    const results: Array<RowDTO> = [];
    let active = 0;
    let index = 0;

    const run = async (): Promise<void> => {
      while (index < items.length) {
        const currentIndex = index;
        index += 1;
        const item = items[currentIndex];
        active += 1;
        Logger.log(`[${currentIndex}] Starting item. Active: ${active}`);

        try {
          const result = await processItem(item);
          results[currentIndex] = result;
        } catch (error) {
          Logger.error(`error in processing in chunks: ${error}`, error.stack);
        } finally {
          active -= 1;
          Logger.log(`[${currentIndex}] Finished item. Active: ${active}`);
        }
      }
    };

    const workers = Array.from({ length: concurrency }, run);
    await Promise.all(workers);
    return results;
  }

  /* Public static async processInChunksArray<T, TResult>(
    items: Array<T>,
    chunkSize: number,
    processChunk: (chunk: Array<T>) => Promise<Array<TResult>>,
  ): Promise<Array<TResult>> {
    const results: Array<TResult> = [];
    let index = 0;

    while (index < items.length) {
      const chunk = items.slice(index, index + chunkSize);
      try {
        const chunkResults = await processChunk(chunk);
        results.push(...chunkResults);
      } catch (error) {
        // Optionally handle/log errors for this chunk
        Logger.error(`Error processing chunk at index ${index}: ${error}`);
      }
      index += chunkSize;
    }

    return results;
  } */

  public static async processInChunksArray<T, TResult>(
    items: Array<T>,
    chunkSize: number,
    processChunk: (chunk: Array<T>) => Promise<Array<TResult>>,
    sortFunction?: (a: T, b: T) => number,
    concurrencyLimit = 5, // Optional limit
  ): Promise<Array<TResult>> {
    const limit = pLimit(concurrencyLimit);
    const chunkPromises: Array<Promise<Array<TResult>>> = [];
    if (sortFunction) {
      items.sort(sortFunction);
    }
    for (let index = 0; index < items.length; index += chunkSize) {
      const chunk = items.slice(index, index + chunkSize);
      chunkPromises.push(
        limit(() =>
          processChunk(chunk).catch((error) => {
            Logger.error(`Error processing chunk at index ${index}: ${error}`);
            return [];
          }),
        ),
      );
    }
    const chunkResults = await Promise.all(chunkPromises);
    return chunkResults.flat();
  }
}

import { DateTime } from 'luxon';

/**
 * Converts a date from a specific timezone to UTC.
 * @param date - The date to convert.
 * @param timezone - The timezone of the date.
 * @returns The date in UTC.
 */
export function convertToUTC(date: string | Date, timezone: string): Date {
  const dateTime =
    typeof date === 'string'
      ? DateTime.fromISO(date, { zone: timezone })
      : DateTime.fromJSDate(date, { zone: timezone });

  if (!dateTime.isValid) {
    throw new Error('Invalid date format');
  }

  return dateTime.toUTC().toJSDate();
}
/**
 * Converts a date from UTC to a specific timezone.
 * @param date - The date in UTC to convert.
 * @param timezone - The target timezone.
 * @returns The date in the specified timezone.
 */
export function convertFromUTC(date: string | Date, timezone: string): string {
  const dateTime =
    typeof date === 'string'
      ? DateTime.fromISO(date, { zone: 'utc' })
      : DateTime.fromJSDate(date, { zone: 'utc' });

  if (!dateTime.isValid) {
    throw new Error('Invalid date format');
  }

  return dateTime.setZone(timezone).toFormat('yyyy-MM-dd HH:mm:ss.SSS');
}

/**
 * Pads a numeric string with leading zeros to reach 18 digits.
 * If the value contains non-numeric characters, it returns the original value unchanged.
 * @param value - The string value to pad
 * @returns The padded string (18 digits) if numeric, otherwise the original value
 * @example
 * padNumericTo18Digits('5558380') // returns '000000000005558380'
 * padNumericTo18Digits('1038879X01') // returns '1038879X01' (unchanged, contains 'X')
 * padNumericTo18Digits('') // returns ''
 * padNumericTo18Digits(undefined) // returns ''
 */
export function padNumericTo18Digits(value: string | undefined): string {
  if (!value) return '';
  // Check if the value is all numeric
  if (/^\d+$/.test(value)) {
    return value.padStart(18, '0');
  }
  return value;
}

import * as xml2js from 'xml2js';
import { SoapFaultResponse } from '@/module/wk-integration/interfaces/soap-fault-response.interface.dto';
import { SoapKeys } from '@/module/wk-integration/interfaces/soap-keys.dto';
/**
 * Builds a SOAP Fault response message.
 * @param faultString The fault message string describing the error.
 * @param faultCode The fault code to indicate the type of fault. Defaults to 'soap:Client'.
 * @returns The SOAP Fault response message as a string.
 */
export function buildSoapFaultResponse(
  faultString: string,
  faultCode = 'soap:Client',
): string {
  const soapFaultResponse: SoapFaultResponse = {
    $: {
      [SoapKeys.XMLNS_SOAP]: 'http://schemas.xmlsoap.org/soap/envelope/',
      [SoapKeys.XMLNS_XSD]: 'http://www.w3.org/2001/XMLSchema',
      [SoapKeys.XMLNS_XSI]: 'http://www.w3.org/2001/XMLSchema-instance',
    },
    [SoapKeys.SOAP_BODY]: {
      [SoapKeys.SOAP_FAULT]: {
        faultcode: faultCode,
        faultstring: faultString,
      },
    },
  };

  const builder = new xml2js.Builder({
    rootName: 'soap:Envelope',
    xmldec: { encoding: 'utf8', version: '1.0' },
  });

  return builder.buildObject(soapFaultResponse);
}

